"""No-API smoke test: imports + schemas + fonts + a real composite call.

Run with:
    python -m autodesign.smoke

Generates `out/smoke/` containing poster.psd, poster.svg, preview.png produced
from a fake (solid-color) background + 2 real text layers rendered via Pillow.
This proves the whole pipeline below the LLM/Gemini layer works without keys.
"""

from __future__ import annotations

import json
import base64
import os
import re
import shlex
import sys
from copy import deepcopy
from dataclasses import replace
from datetime import datetime
from io import BytesIO
from pathlib import Path
from typing import Any

from PIL import Image
from pydantic import ValidationError

from .schema import (
    CompositionArtifacts, CritiqueResult, DesignSpec, HtmlBlock, LayerNode, RunResult,
    SafeZone, TextEffect, ThinkingBlockRecord, ToolResultRecord,
)


def _fail(msg: str) -> None:
    print(f"  FAIL  {msg}")
    sys.exit(1)


def _ok(msg: str) -> None:
    print(f"  ok    {msg}")


def check_imports() -> None:
    print("[1/53] imports")
    from . import chat, cli, config, designer, runner, schema, session  # noqa
    from .agents import CriticAgent, PromptEnhancer  # noqa
    from . import skills  # noqa
    from .tools import (
        TOOL_HANDLERS, TOOL_SCHEMAS, ToolContext,
        apply_design_ops, composite, critique_tool, edit_layer,
        fetch_brand_asset, finalize, generate_background, generate_visual_reference,
        propose_design_spec, propose_paper_poster_html, render_text_layer,
        read_skill_resource, retrieve_paper_context, switch_artifact_type,
    )  # noqa
    from .util import ids, io, layout_grounder, logging  # noqa
    _ok("all modules import (incl. chat + session + edit_layer)")


def check_tool_registry() -> None:
    print("[2/53] tool registry")
    from .tools import TOOL_HANDLERS, TOOL_SCHEMAS

    expected = {"switch_artifact_type", "propose_paper_poster_html", "propose_design_spec",
                "generate_background", "generate_image",
                "generate_visual_reference", "render_text_layer",
                "edit_layer", "apply_design_ops",
                "fetch_brand_asset", "composite", "critique", "finalize",
                "ingest_document", "retrieve_paper_context",
                "read_skill_resource", "discover_paper_resources", "export_video"}
    schema_names = {s["name"] for s in TOOL_SCHEMAS}
    handler_names = set(TOOL_HANDLERS.keys())
    missing = expected - (schema_names & handler_names)
    extra = (schema_names | handler_names) - expected
    if missing:
        _fail(f"missing tools: {missing}")
    if extra:
        _fail(f"unexpected tools: {extra}")
    for s in TOOL_SCHEMAS:
        for k in ("name", "description", "input_schema"):
            if k not in s:
                _fail(f"tool '{s.get('name','?')}' missing key '{k}'")
        if s["input_schema"].get("type") != "object":
            _fail(f"tool '{s['name']}' input_schema.type != 'object'")
    # switch_artifact_type should be first in TOOL_SCHEMAS (pedagogical ordering)
    if TOOL_SCHEMAS[0]["name"] != "switch_artifact_type":
        _fail(f"switch_artifact_type should be first in TOOL_SCHEMAS; got {TOOL_SCHEMAS[0]['name']}")
    _ok(f"{len(expected)} tools wired (schemas + handlers): {sorted(schema_names)}")


def check_paper_memory_retrieval_no_api() -> None:
    print("[2b/53] paper memory retrieval")
    from types import SimpleNamespace

    from .tools import ToolContext
    from .tools.retrieve_paper_context import retrieve_paper_context
    from .agents import PaperMemoryAgent
    from .config import Settings
    from .util.paper_memory import (
        build_paper_memory,
        compact_paper_memory_for_planner,
        paper_memory_markdown,
        paper_memory_cache_dir,
        read_paper_memory_cache,
        retrieve_paper_context as retrieve_from_memory,
        write_paper_memory_cache,
        write_paper_memory_run_artifacts,
    )
    from .util.paper_memory_dossier import (
        read_paper_memory_dossier_cache,
        retrieve_from_paper_memory_dossier,
        validate_paper_memory_dossier,
        write_paper_memory_dossier_cache,
        write_paper_memory_dossier_run_artifacts,
    )

    out_dir = Path("out/smoke_paper_memory")
    layers_dir = out_dir / "layers"
    layers_dir.mkdir(parents=True, exist_ok=True)
    pdf_path = out_dir / "paper.pdf"
    pdf_path.write_bytes(b"%PDF-1.4\n% fake smoke paper\n")
    body_window = {
        "total_page_count": 4,
        "body_page_count": 3,
        "references_start_page": 4,
        "appendix_start_page": None,
        "cutoff_start_page": 4,
        "cutoff_reason": "references",
        "source_scope": "body",
    }
    manifest = {
        "title": "Memory Smoke Paper",
        "authors": ["A. Author", "B. Researcher"],
        "abstract": "We test a retrieval memory for paper posters.",
        "sections": [
            {"title": "Method", "summary": "The method uses a two-stage retrieval pipeline.", "page": 2},
            {"title": "Results", "summary": "The benchmark improves accuracy by 12.5% over the baseline.", "page": 3},
        ],
        "figures": [{"caption": "Figure 1 shows the retrieval pipeline.", "page": 2}],
        "tables": [{"caption": "Table 1 reports accuracy and latency.", "page": 3}],
    }
    rendered = {
        "ingest_table_01": {
            "kind": "table",
            "source_page": 3,
            "caption": "Table 1 reports accuracy and latency.",
            "headers": ["Model", "Accuracy"],
            "rows": [["Baseline", "70.0"], ["Ours", "82.5"]],
        }
    }
    memory = build_paper_memory(
        pdf_path=pdf_path,
        page_texts=[
            "Memory Smoke Paper. A. Author and B. Researcher.",
            "The method uses a two-stage retrieval pipeline for planner evidence.",
            "The benchmark improves accuracy by 12.5% over the baseline in Table 1.",
        ],
        manifest=manifest,
        body_window=body_window,
        rendered_layers=rendered,
        registered_layer_ids=["ingest_table_01"],
        recommended_text_units={
            "evidence": [{
                "text": "The benchmark improves accuracy by 12.5% over the baseline.",
                "source": "section:2",
                "source_ids": ["ingest_table_01"],
                "page": 3,
            }]
        },
    )
    if memory.get("version") != 2:
        _fail(f"paper memory version should be 2; got {memory.get('version')}")
    if not memory.get("evidence_kinds"):
        _fail("paper memory did not record evidence kind counts")
    settings = SimpleNamespace(out_dir=str(out_dir))
    cache_path = write_paper_memory_cache(settings, memory)
    if not cache_path or not cache_path.exists():
        _fail("paper memory cache was not written")
    cache_dir = paper_memory_cache_dir(settings, str(memory.get("cache_key")))
    if not (cache_dir / "payload.json").exists():
        _fail("paper memory cache path did not use out/cache/paper_memory/<key>/payload.json")
    for rel in ("index.json", "memory.md", "evidence_packs/results.md"):
        if not (cache_dir / rel).exists():
            _fail(f"paper memory cache sidecar missing {rel}")
    cached = read_paper_memory_cache(settings, str(memory.get("cache_key")))
    if not cached or cached.get("cache_key") != memory.get("cache_key"):
        _fail("paper memory cache hit did not return the same key")
    compact_memory = compact_paper_memory_for_planner(cached)
    if len(compact_memory.get("sample_chunks") or []) != int(cached.get("chunk_count") or 0):
        _fail("planner paper-memory projection should include all chunks by default")
    if "Paper memory projection truncated" in paper_memory_markdown(cached):
        _fail("paper_memory_markdown should not truncate by default")
    run_paths = write_paper_memory_run_artifacts(out_dir / "run_memory", cached)
    for key in ("paper_memory_json", "paper_memory_md", "paper_evidence_packs"):
        if not run_paths.get(key) or not Path(run_paths[key]).exists():
            _fail(f"paper memory run artifact missing {key}")
    result = retrieve_from_memory(
        cached,
        query="accuracy baseline improvement",
        categories=["numeric_claim", "result_unit", "table_row"],
        evidence_kind=["extracted", "normalized_table"],
        top_k=3,
    )
    if not result.get("results"):
        _fail(f"paper memory retrieval returned no snippets: {result}")
    if not any("12.5" in str(item.get("quote") or item.get("text") or "") for item in result["results"]):
        _fail(f"paper memory retrieval missed numeric/table evidence: {result}")
    safe_result = retrieve_from_memory(
        cached,
        query="retrieval pipeline",
        evidence_kind=["extracted"],
        safe_to_quote=True,
        top_k=2,
    )
    if not safe_result.get("results") or not all(item.get("safe_to_quote") for item in safe_result["results"]):
        _fail(f"paper memory safe-to-quote filter failed: {safe_result}")
    all_table_rows = retrieve_from_memory(
        cached,
        query="accuracy",
        categories=["table_row"],
    )
    if len(all_table_rows.get("results") or []) < 2 or all_table_rows.get("top_k") != len(all_table_rows.get("results") or []):
        _fail(f"paper memory retrieval should return all matches when top_k is omitted: {all_table_rows}")
    limited_table_rows = retrieve_from_memory(
        cached,
        query="accuracy",
        categories=["table_row"],
        top_k=1,
    )
    if len(limited_table_rows.get("results") or []) != 1:
        _fail(f"explicit top_k should still limit retrieval: {limited_table_rows}")

    result_chunk = next(
        (
            chunk for chunk in cached.get("chunks") or []
            if (
                isinstance(chunk, dict)
                and chunk.get("safe_to_quote")
                and "12.5" in str(chunk.get("quote") or chunk.get("text") or "")
            )
        ),
        None,
    )
    method_chunk = next(
        (
            chunk for chunk in cached.get("chunks") or []
            if (
                isinstance(chunk, dict)
                and chunk.get("safe_to_quote")
                and "two-stage retrieval" in str(chunk.get("quote") or chunk.get("text") or "")
            )
        ),
        None,
    )
    if not result_chunk or not method_chunk:
        _fail("paper memory fixture did not expose expected chunks for dossier tests")
    valid_dossier_input = {
        "kind": "paper_memory_dossier",
        "version": 1,
        "source_memory_cache_key": cached.get("cache_key"),
        "model": "stub-paper-memory",
        "sections": [
            {
                "id": "results",
                "panel_role": "results_table",
                "title": "Benchmark lift",
                "claim": "The memory smoke method improves accuracy over the baseline.",
                "poster_copy_suggestion": "Use the result table to show the 12.5 point improvement over baseline.",
                "visual_ids": ["ingest_table_01"],
                "confidence": 0.92,
                "evidence_refs": [{
                    "chunk_id": result_chunk.get("chunk_id"),
                    "quote": result_chunk.get("quote"),
                    "safe_to_quote": result_chunk.get("safe_to_quote"),
                    "page": result_chunk.get("page"),
                    "source_id": result_chunk.get("source_id"),
                }],
            },
            {
                "id": "method",
                "panel_role": "method_pipeline",
                "title": "Two-stage retrieval",
                "claim": "The method uses a two-stage retrieval pipeline.",
                "poster_copy_suggestion": "Explain the two-stage retrieval pipeline before showing result evidence.",
                "visual_ids": [],
                "confidence": 0.88,
                "evidence_refs": [{
                    "chunk_id": method_chunk.get("chunk_id"),
                    "quote": method_chunk.get("quote"),
                    "safe_to_quote": method_chunk.get("safe_to_quote"),
                }],
            },
        ],
    }
    valid_dossier, dossier_errors = validate_paper_memory_dossier(cached, valid_dossier_input)
    if dossier_errors or len(valid_dossier.get("sections") or []) != 2:
        _fail(f"valid dossier failed validation: {dossier_errors}")
    bad_dossier, bad_errors = validate_paper_memory_dossier(
        cached,
        {
            "kind": "paper_memory_dossier",
            "version": 1,
            "source_memory_cache_key": cached.get("cache_key"),
            "sections": [{
                "id": "bad",
                "panel_role": "results_table",
                "title": "Bad",
                "claim": "Bad",
                "poster_copy_suggestion": "Bad",
                "evidence_refs": [{"chunk_id": "paper:nope", "quote": "fabricated quote"}],
            }],
        },
    )
    if bad_dossier.get("sections") or not any("missing_chunk_id" in err for err in bad_errors):
        _fail(f"invalid dossier did not reject missing chunk refs: {bad_errors}")
    quote_bad, quote_bad_errors = validate_paper_memory_dossier(
        cached,
        {
            **valid_dossier_input,
            "sections": [{
                **valid_dossier_input["sections"][0],
                "evidence_refs": [{
                    "chunk_id": result_chunk.get("chunk_id"),
                    "quote": "fabricated exact quote not in chunk",
                    "safe_to_quote": True,
                }],
            }],
        },
    )
    if quote_bad.get("sections") and not quote_bad_errors:
        _fail("fabricated quote was accepted without validation errors")

    if not write_paper_memory_dossier_cache(settings, cached, valid_dossier):
        _fail("paper memory dossier cache was not written")
    cached_dossier = read_paper_memory_dossier_cache(settings, cached, model="stub-paper-memory")
    if not cached_dossier or cached_dossier.get("source_memory_cache_key") != cached.get("cache_key"):
        _fail("paper memory dossier cache hit failed")
    all_curated = retrieve_from_paper_memory_dossier(
        cached_dossier,
        cached,
        query="retrieval benchmark",
        needs=["copy"],
    )
    if len(all_curated.get("results") or []) != len(cached_dossier.get("sections") or []):
        _fail(f"dossier retrieval should return all matches when top_k is omitted: {all_curated}")
    dossier_paths = write_paper_memory_dossier_run_artifacts(out_dir / "run_memory", cached_dossier)
    for key in ("paper_memory_dossier_json", "paper_memory_dossier_md"):
        if not dossier_paths.get(key) or not Path(dossier_paths[key]).exists():
            _fail(f"paper memory dossier run artifact missing {key}")
    curated = retrieve_from_paper_memory_dossier(
        cached_dossier,
        cached,
        query="lazy user asks for best benchmark result",
        panel_role="results_table",
        needs=["copy", "table"],
        top_k=2,
    )
    if not curated.get("results") or curated["results"][0].get("source") != "dossier":
        _fail(f"dossier retrieval failed: {curated}")
    if "12.5" not in str(curated["results"][0].get("poster_copy_suggestion") or curated["results"][0].get("quote") or ""):
        _fail(f"dossier retrieval missed curated result copy: {curated}")
    expanded = retrieve_from_paper_memory_dossier(
        cached_dossier,
        cached,
        query="lazy user asks for two-stage retrieval details",
        panel_role="method_pipeline",
        needs=["copy", "expanded_text"],
        top_k=2,
    )
    expanded_refs = (expanded.get("results") or [{}])[0].get("evidence_refs") or []
    if not expanded_refs or "two-stage retrieval" not in str(expanded_refs[0].get("chunk_text") or ""):
        _fail(f"dossier expanded_text retrieval missed raw chunk text: {expanded}")

    ctx = ToolContext(settings=settings, run_dir=out_dir / "run", layers_dir=layers_dir, run_id="smoke")
    ctx.state["paper_memory"] = cached
    ctx.state["paper_memory_dossier"] = cached_dossier
    obs = retrieve_paper_context(
        {
            "query": "two-stage retrieval method",
            "panel_role": "method_pipeline",
            "evidence_kind": ["extracted"],
            "safe_to_quote": True,
            "expand_evidence_refs": True,
            "top_k": 2,
        },
        ctx=ctx,
    )
    if obs.status != "ok" or not obs.payload.get("results"):
        _fail(f"retrieve_paper_context tool failed: {obs}")
    if obs.payload.get("source") != "dossier":
        _fail(f"hybrid retrieve_paper_context should prefer dossier: {obs.payload}")
    tool_refs = (obs.payload.get("results") or [{}])[0].get("evidence_refs") or []
    if not tool_refs or "two-stage retrieval" not in str(tool_refs[0].get("chunk_text") or ""):
        _fail(f"retrieve_paper_context expand_evidence_refs missed chunk_text: {obs.payload}")
    raw_obs = retrieve_paper_context(
        {
            "query": "two-stage retrieval method",
            "mode": "raw",
            "top_k": 2,
        },
        ctx=ctx,
    )
    if raw_obs.status != "ok" or raw_obs.payload.get("source") != "lexical":
        _fail(f"raw retrieve_paper_context should preserve lexical retrieval: {raw_obs}")

    agent_settings = Settings(
        anthropic_api_key="sk-stub",
        anthropic_base_url=None,
        gemini_api_key="stub",
        designer_model="stub-planner",
        critic_model="stub-critic",
        paper_memory_model="stub-paper-memory",
        paper_memory_max_turns=3,
        paper_memory_thinking_budget=0,
        out_dir=out_dir,
    )
    agent = PaperMemoryAgent(agent_settings)
    agent.backend = _MockCriticBackend(
        model="stub-paper-memory",
        turns=[
            _ScriptedTurn(tool_calls=[
                ("report_paper_memory_dossier", {
                    "kind": "paper_memory_dossier",
                    "version": 1,
                    "source_memory_cache_key": cached.get("cache_key"),
                    "sections": [{
                        "id": "bad",
                        "panel_role": "results_table",
                        "title": "Bad",
                        "claim": "Bad",
                        "poster_copy_suggestion": "Bad",
                        "evidence_refs": [{"chunk_id": "paper:nope", "quote": "fabricated"}],
                    }],
                }),
            ]),
            _ScriptedTurn(tool_calls=[
                ("report_paper_memory_dossier", valid_dossier_input),
            ]),
        ],
    )
    agent._system_prompt = "patched"
    agent_dossier = agent.build(memory=cached, manifest=manifest)
    if len(agent_dossier.get("sections") or []) != 2:
        _fail(f"paper memory agent did not retry into valid dossier: {agent_dossier}")
    _ok(f"{memory.get('chunk_count')} chunks; top retrieval {obs.payload['results'][0]['category']}")


def check_pydantic_roundtrip() -> None:
    """Runtime schema + design-session event roundtrip."""
    print("[3/53] runtime schema + design events")
    from .config import REPO_ROOT
    from .util.design_events import (
        append_design_event, layer_edit_events, session_events_path,
    )

    plain_thinking = ThinkingBlockRecord(
        thinking="I should declare poster type then propose a 3:4 spec.",
        signature="sig_opaque_anthropic",
        is_redacted=False,
    )
    redacted_thinking = ThinkingBlockRecord(
        thinking="",
        signature="enc_payload_bytes",
        is_redacted=True,
    )
    ok_result = ToolResultRecord(
        status="ok",
        payload={"layer_id": "L1", "sha256": "deadbeef", "width": 1536, "height": 2048},
    )
    err_result = ToolResultRecord(
        status="error",
        error_message="DesignSpec validation failed: missing canvas.w_px",
        error_category="validation",
        payload={"hint": None},
    )
    crit = CritiqueResult(iteration=1, verdict="pass", score=0.86,
                          issues=[], rationale="reads as a coherent poster")
    crit_payload = ToolResultRecord(status="ok", payload=crit.model_dump(mode="json"))
    result = RunResult(
        run_id="smoke",
        run_dir=str(REPO_ROOT / "out" / "smoke"),
        artifact_type="poster",
        terminal_status="pass",
        critic_verdict="pass",
        critic_score=0.86,
        n_layers=5,
        n_critiques=1,
        finalize_notes="all done",
        wall_s=187.5,
        designer_model="claude-opus-4-7",
        critic_model="claude-opus-4-7",
        image_model="gemini-3-pro-image-preview",
        total_input_tokens=1234,
        total_output_tokens=200,
        selected_skills=["common.export_qa"],
        visual_reference={"visual_reference_status": "success"},
    )
    dumped = result.model_dump(mode="json")
    serialized = json.dumps(dumped, ensure_ascii=False)
    try:
        reloaded = RunResult.model_validate(json.loads(serialized))
    except ValidationError as e:
        _fail(f"RunResult round-trip: {e.errors()[:3]}")

    if reloaded.terminal_status != "pass":
        _fail(f"terminal_status not preserved: {reloaded.terminal_status}")
    if reloaded.critic_score != 0.86:
        _fail(f"critic_score not preserved: {reloaded.critic_score}")
    if reloaded.selected_skills != ["common.export_qa"]:
        _fail(f"selected_skills not preserved: {reloaded.selected_skills}")
    if reloaded.visual_reference.get("visual_reference_status") != "success":
        _fail(f"visual_reference summary not preserved: {reloaded.visual_reference}")
    if plain_thinking.thinking != "I should declare poster type then propose a 3:4 spec.":
        _fail("thinking text corrupted")
    if not redacted_thinking.is_redacted:
        _fail("redacted thinking flag lost")
    if not err_result.error_message:
        _fail("error_message stripped from tool_result")
    if err_result.error_category != "validation":
        _fail(f"error_category lost: {err_result.error_category}")
    if ok_result.payload.get("layer_id") != "L1":
        _fail("tool result payload lost")
    if crit_payload.payload.get("score") != 0.86:
        _fail("critique payload (verdict/score/issues) lost")
    styled_layer = LayerNode(
        layer_id="T_style",
        name="Typographic title",
        kind="text",
        z_index=3,
        bbox=SafeZone(x=0, y=0, w=600, h=120),
        text="Typography",
        font_family="NotoSerifSC",
        font_size_px=72,
        font_weight=720,
        font_style="italic",
        line_height=1.04,
        letter_spacing=1.5,
        text_transform="uppercase",
        align="center",
        effects=TextEffect(fill="#111111"),
    )
    styled_roundtrip = LayerNode.model_validate(
        json.loads(json.dumps(styled_layer.model_dump(mode="json")))
    )
    if (
        styled_roundtrip.font_weight != 720
        or styled_roundtrip.font_style != "italic"
        or styled_roundtrip.line_height != 1.04
        or styled_roundtrip.letter_spacing != 1.5
        or styled_roundtrip.text_transform != "uppercase"
    ):
        _fail(f"typography fields did not round-trip: {styled_roundtrip}")

    out_dir = REPO_ROOT / "out" / "smoke_design_events"
    conv_id = "smoke_conversation"
    event_path = session_events_path(out_dir, conv_id)
    event_path.unlink(missing_ok=True)
    append_design_event(
        out_dir, conv_id, "message.user_submitted",
        run_id="smoke", data={"brief": "design a 3:4 poster"},
    )
    diffs = layer_edit_events(
        [{"layer_id": "L1", "text": "A", "font_size_px": 90,
          "bbox": {"x": 0, "y": 0, "w": 100, "h": 50},
          "effects": {"fill": "#000000"}}],
        [{"layer_id": "L1", "text": "B", "font_size_px": 110,
          "bbox": {"x": 5, "y": 0, "w": 100, "h": 50},
          "effects": {"fill": "#ff3366"}}],
    )
    if len(diffs) != 1 or diffs[0]["before"]["text"] != "A" or diffs[0]["after"]["text"] != "B":
        _fail(f"layer_edit_events produced bad diff: {diffs}")
    append_design_event(
        out_dir, conv_id, "layer.edited",
        run_id="smoke", artifact_id="art_smoke", data=diffs[0],
    )
    lines = event_path.read_text(encoding="utf-8").splitlines()
    if len(lines) != 2:
        _fail(f"design event jsonl should contain 2 events, got {len(lines)}")
    if json.loads(lines[1])["data"]["after"]["fill"] != "#ff3366":
        _fail("layer edit fill diff not persisted")

    _ok(f"RunResult + ToolResultRecord roundtrip; design events JSONL append ({len(serialized)} bytes)")


def check_runtime_skills_no_api() -> None:
    print("[3d/53] runtime skills (no API)")
    from .config import REPO_ROOT, Settings
    from .skills import inject_skill_context, load_builtin_skills, select_skills
    from .util.academic_palette import (
        load_academic_palette_library,
        rank_academic_color_system_options,
        select_academic_color_system,
    )

    settings = Settings(
        anthropic_api_key="stub",
        anthropic_base_url=None,
        gemini_api_key="",
        designer_model="stub-planner",
        critic_model="stub-critic",
    )
    registry = load_builtin_skills(settings)
    loaded_ids = {p.id for p in registry.packs}
    expected = {
        "common.export_qa",
        "common.source_analysis_flow",
        "common.pdf_visual_curation",
        "common.pdf_render_qa",
        "common.playwright_browser_qa",
        "deck.paper2deck_provenance",
        "deck.report2deck_general",
        "deck.ppt_beautify",
        "deck.html_ppt_general",
        "poster.table_craft",
        "poster.visual_recipe",
        "landing.visual_recipe",
    }
    if not expected.issubset(loaded_ids):
        _fail(f"builtin skills missing: expected {expected}, got {loaded_ids}")

    palette_library = load_academic_palette_library()
    palette_ids = [item.get("id") for item in palette_library.get("palettes") or []]
    expected_palette_ids = ['bright_cobalt',
 'teal_coral',
 'plum_sage',
 'tangerine_blue',
 'blossom_teal',
 'lavender_forest',
 'mulberry_mint',
 'deep_navy',
 'petrol_teal',
 'burnt_orange',
 'oxide_red',
 'wine_rose',
 'deep_cyan']
    if palette_ids != expected_palette_ids:
        _fail(f"academic palette library ids changed: {palette_ids}")
    palette_by_id = {item["id"]: item for item in palette_library.get("palettes") or []}
