            ".flow-asset{width:64%;max-height:80px;overflow:hidden;margin:0 18px 14px 0;}"
            ".float-right{float:right;shape-outside:inset(0 round 8px);}"
            ".flow-asset img{width:100%;height:auto;max-height:inherit;object-fit:contain;}"
