def check_paper_resource_discovery_no_api() -> None:
    print("[3h2a/53] paper resource discovery from source text (no API)")
    from .config import Settings
    from .tools import ToolContext
    from .tools.discover_paper_resources import discover_paper_resources_for_context

    out_dir = Path("out/smoke_paper_resource_discovery")
    layers_dir = out_dir / "layers"
    layers_dir.mkdir(parents=True, exist_ok=True)
    ctx = ToolContext(
        settings=Settings(
            anthropic_api_key="sk-stub",
            anthropic_base_url=None,
            gemini_api_key="stub",
            designer_model="stub-planner",
            critic_model="stub-critic",
        ),
        run_dir=out_dir,
        layers_dir=layers_dir,
        run_id="smoke-paper-resource-discovery",
    )
    ctx.state["ingested"] = [{
        "type": "pdf",
        "manifest": {
            "title": "Resource Discovery Smoke Paper",
            "authors": ["A. Author"],
        },
        "raw_text": (
            "Project resources: https://github.com/example/smoke-paper "
            "and https://huggingface.co/example/smoke-model. "
            "Split PDF URL: https://github.com/ example/smoke-paper-v2. "
            "Preprint arXiv: 2401.12345."
        ),
    }]
    manifest = discover_paper_resources_for_context(
        ctx,
        max_results=8,
        search_web=False,
    )
    hrefs = {item.get("href") for item in manifest.get("resources") or []}
    for expected in (
        "https://github.com/example/smoke-paper",
        "https://github.com/example/smoke-paper-v2",
        "https://huggingface.co/example/smoke-model",
        "https://arxiv.org/abs/2401.12345",
    ):
        if expected not in hrefs:
            _fail(f"paper resource discovery missed {expected}: {manifest}")
    chips = manifest.get("resource_chips") or []
    if not any(chip.get("icon") == "GH" for chip in chips):
        _fail(f"GitHub resource chip icon missing: {chips}")
    recall_audit = manifest.get("resource_recall_audit") or {}
    if recall_audit.get("paper_text_url_count", 0) < 4:
        _fail(f"paper resource recall audit missed source-text URLs: {recall_audit}")
    if "github" not in (recall_audit.get("coverage_by_type") or {}):
        _fail(f"paper resource recall audit missed GitHub coverage: {recall_audit}")
    if not any(item.get("evidence") for item in manifest.get("resources") or []):
        _fail(f"paper resources should retain source evidence snippets: {manifest}")
    if not (out_dir / "paper_resource_manifest.json").exists():
        _fail("paper resource discovery should write paper_resource_manifest.json")
    if not (out_dir / "paper_resource_recall_audit.json").exists():
        _fail("paper resource discovery should write paper_resource_recall_audit.json")
    _ok("source text URLs become real resource chips")


