            {"layer_id": "evidence_caption", "kind": "text", "text": "Evidence visual", "bbox": {"x": 500, "y": 430, "w": 460, "h": 30}},
            {"layer_id": "problem_label", "kind": "text", "text": "Problem", "bbox": {"x": 30, "y": 40, "w": 200, "h": 30}},
            {"layer_id": "method_label", "kind": "text", "text": "Method", "bbox": {"x": 30, "y": 80, "w": 200, "h": 30}},
            {"layer_id": "evidence_label", "kind": "text", "text": "Main Evidence", "bbox": {"x": 500, "y": 80, "w": 260, "h": 30}},
            {"layer_id": "takeaway_label", "kind": "text", "text": "Takeaway", "bbox": {"x": 20, "y": 500, "w": 260, "h": 30}},
