def check_pdf_visual_ingest_audit_no_api() -> None:
    print("[3f2/53] pdf visual ingest audit metrics (no API)")
    import importlib.util

    from .config import REPO_ROOT

    module_path = REPO_ROOT / "scripts" / "audit_pdf_visual_ingest.py"
    spec = importlib.util.spec_from_file_location("smoke_audit_pdf_visual_ingest", module_path)
    if spec is None or spec.loader is None:
        _fail(f"could not load audit module from {module_path}")
    audit = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(audit)

    selected_ids = ["ingest_fig_01", "ingest_table_01"]
    contract = {
        "poster_visual_unit_target": 4,
        "selected_source_visual_count": 2,
        "supplemental_native_visual_tasks": [{
            "task_id": "native_pipeline",
            "title": "Editable pipeline schematic",
            "instruction": "Draw a native HTML/SVG method unit from source text.",
            "source_ids": ["section:method"],
        }, {
            "task_id": "native_table",
            "title": "Editable result summary",
            "instruction": "Build a native paper-grounded table from source text.",
            "source_ids": ["section:results"],
        }],
    }
    content = {"visual_selection": {"target_visual_count": 4}}
    source_metrics = audit._selected_source_visual_metrics(
        selected_ids=selected_ids,
        contract=contract,
        content=content,
    )
    if source_metrics.get("selected_source_visual_count") != 2:
        _fail(f"audit selected source count did not prefer contract metric: {source_metrics}")
    if source_metrics.get("poster_visual_unit_target") != 4 or source_metrics.get("source_visual_shortfall") != 2:
        _fail(f"audit source shortfall metrics wrong: {source_metrics}")
    if source_metrics.get("supplemental_native_visual_task_count") != 2:
        _fail(f"audit native visual task count missing: {source_metrics}")

    registered_assets = [
        {"asset_id": "ingest_fig_01", "kind": "image", "asset_class": "source_figure", "planner_visible": True},
        {"asset_id": "ingest_table_01", "kind": "table", "asset_class": "source_table", "planner_visible": True},
    ]
    selected_review = audit._selected_asset_review(
        selected_ids=selected_ids,
        contract=contract,
        storyboard={},
        content=content,
        registered_assets=registered_assets,
        contract_bad_assets=[],
        designer_ineligible_assets=[],
        candidate_diagnostics={},
    )
    if selected_review.get("issue_assets"):
        _fail(f"clean selected source assets should not become bad selected assets: {selected_review}")
    review_metrics = audit._paper_review_metrics(
        status="ok",
        registered_asset_count=2,
        planner_visible_registered_asset_count=2,
        designer_eligible_asset_count=2,
        designer_ineligible_assets=[],
        contract_bad_assets=[],
        selected_asset_review=selected_review,
        source_visual_metrics=source_metrics,
        table_leak_assets=[],
        figure_leak_assets=[],
        zero_asset_paper=False,
        low_asset_paper=False,
    )
    if review_metrics.get("selected_weak_quality_count") != 0:
        _fail(f"low source count should not be reported as selected asset quality failure: {review_metrics}")
    if (
        review_metrics.get("source_visual_shortfall") != 2
        or review_metrics.get("unbacked_source_visual_shortfall") != 0
        or not audit._review_metrics_pass(review_metrics)
    ):
        _fail(f"source shortfall backed by native tasks should pass selected quality review: {review_metrics}")
    underbacked_metrics = audit._paper_review_metrics(
        status="ok",
        registered_asset_count=2,
        planner_visible_registered_asset_count=2,
        designer_eligible_asset_count=2,
        designer_ineligible_assets=[],
        contract_bad_assets=[],
        selected_asset_review=selected_review,
        source_visual_metrics={**source_metrics, "supplemental_native_visual_task_count": 1},
        table_leak_assets=[],
        figure_leak_assets=[],
        zero_asset_paper=False,
        low_asset_paper=False,
    )
    if underbacked_metrics.get("unbacked_source_visual_shortfall") != 1 or audit._review_metrics_pass(underbacked_metrics):
        _fail(f"unbacked source shortfall should remain a failing audit issue: {underbacked_metrics}")
    rollup = audit._index_review_rollup([{
        "name": "source-shortfall-smoke",
        "status": "ok",
        "selected_asset_review": selected_review,
        "review_metrics": review_metrics,
        **review_metrics,
    }])
    if (
        rollup.get("selected_issue_asset_count") != 0
        or rollup.get("source_visual_shortfall_paper_count") != 1
        or rollup.get("unbacked_source_visual_shortfall_paper_count") != 0
    ):
        _fail(f"source shortfall should roll up separately from bad selected assets: {rollup}")
    _ok("audit separates backed and unbacked selected-source shortfall from selected asset quality")


def check_academic_identity_search_resolver_no_api() -> None:
    print("[8b/53] academic identity search resolver (no API)")
    import shutil

    from .config import REPO_ROOT
    from .util.academic_identity_search import (
        FetchedResource,
        find_allowlist_rule,
        resolve_academic_identity_assets,
        resolve_designer_identity_logo_candidates,
    )

    out_dir = REPO_ROOT / "out" / "smoke_identity_search"
    if out_dir.exists():
        shutil.rmtree(out_dir)
    layers_dir = out_dir / "layers"
    layers_dir.mkdir(parents=True, exist_ok=True)
    allowlist_path = out_dir / "allowlist.json"
    allowlist_path.write_text(json.dumps({
        "version": 1,
        "rules": [
            {
                "id": "testconf",
                "entity_name": "TestConf",
                "role": "venue",
                "aliases": ["TestConf"],
                "official_domains": ["testconf.org"],
                "preferred_asset_urls": ["https://testconf.org/assets/testconf-logo.svg"],
                "confidence": 0.86,
            },
            {
                "id": "example-university",
                "entity_name": "Example University",
                "role": "institution",
                "aliases": ["Example University"],
                "official_domains": ["example.edu"],
                "homepages": ["https://example.edu/brand"],
                "confidence": 0.84,
            },
            {
                "id": "company-google-research",
                "entity_name": "Google Research",
                "role": "company",
                "aliases": ["Google Research", "Google"],
                "official_domains": ["research.google", "google.com"],
                "homepages": ["https://research.google/"],
                "confidence": 0.84,
            },
            {
                "id": "brand-example-university",
                "entity_name": "Brand Example University",
                "role": "institution",
                "aliases": ["Brand Example University"],
                "official_domains": ["brand-example.edu"],
                "homepages": ["https://brand-example.edu/brand"],
                "confidence": 0.84,
            },
            {
                "id": "icon-university",
                "entity_name": "Icon University",
                "role": "institution",
                "aliases": ["Icon University"],
                "official_domains": ["icon.edu"],
                "homepages": ["https://icon.edu/"],
                "confidence": 0.84,
            },
            {
                "id": "blocked-university",
                "entity_name": "Blocked University",
                "role": "institution",
                "aliases": ["Blocked University"],
                "official_domains": ["blocked.edu"],
                "preferred_asset_urls": ["https://evil.example/logo.png"],
                "confidence": 0.84,
            },
            {
                "id": "venue-chi",
                "entity_name": "CHI",
                "role": "venue",
                "aliases": ["CHI", "ACM CHI"],
                "official_domains": ["sigchi.org"],
                "confidence": 0.78,
            },
            {
                "id": "institution-chiao-tung",
                "entity_name": "National Chiao Tung University",
                "role": "institution",
                "aliases": ["National Chiao Tung University", "NCTU"],
                "official_domains": ["nctu.edu.tw"],
                "confidence": 0.78,
            },
        ],
    }), encoding="utf-8")
    custom_allowlist = json.loads(allowlist_path.read_text(encoding="utf-8"))
    if (find_allowlist_rule("National Chiao Tung University", role="institution", allowlist=custom_allowlist) or {}).get("id") != "institution-chiao-tung":
        _fail("institution role should not be stolen by short venue alias CHI")
    if (find_allowlist_rule("CHI", role="venue", allowlist=custom_allowlist) or {}).get("id") != "venue-chi":
        _fail("short venue alias CHI should still exact-match the venue rule")

    svg = b"""<svg xmlns="http://www.w3.org/2000/svg" width="180" height="72">
    <rect width="180" height="72" rx="6" fill="#111827"/>
    <circle cx="36" cy="36" r="18" fill="#60a5fa"/>
    <rect x="70" y="26" width="88" height="20" fill="#f8fafc"/>
    </svg>"""
    png_buf = BytesIO()
    Image.new("RGBA", (160, 80), (14, 165, 233, 255)).save(png_buf, format="PNG")
    png_bytes = png_buf.getvalue()
    thumbnail_buf = BytesIO()
    Image.new("RGB", (1920, 1080), (5, 5, 8)).save(thumbnail_buf, format="JPEG")
    thumbnail_bytes = thumbnail_buf.getvalue()
    fetch_calls: list[str] = []

    def fake_fetch(url: str, max_bytes: int) -> FetchedResource:
        fetch_calls.append(url)
        if url == "https://testconf.org/assets/testconf-logo.svg":
            return FetchedResource(url=url, data=svg, content_type="image/svg+xml")
        if url == "https://example.edu/brand":
            html = (
                '<html><body><img class="site-logo" alt="Example University logo" '
                'src="https://cdn.example.net/example-logo.png"></body></html>'
            ).encode()
            return FetchedResource(url=url, data=html, content_type="text/html")
        if url == "https://cdn.example.net/example-logo.png":
            return FetchedResource(url=url, data=png_bytes, content_type="image/png")
        if url == "https://research.google/":
            html = (
                '<html><body><img alt="Google Research anthem film" '
                'src="https://storage.googleapis.com/gweb-research2023-media/images/'
                'USS0291-Google_Research_Anthem_Film_Thumbnail4_.original.jpg"></body></html>'
            ).encode()
            return FetchedResource(url=url, data=html, content_type="text/html")
        if url == (
            "https://storage.googleapis.com/gweb-research2023-media/images/"
            "USS0291-Google_Research_Anthem_Film_Thumbnail4_.original.jpg"
        ):
            return FetchedResource(url=url, data=thumbnail_bytes, content_type="image/jpeg")
        if url == "https://brand-example.edu/brand":
            html = (
                '<html><body><img alt="Brand Example University brand" '
                'src="https://brand-example.edu/images/applying-the-brand-900x600.jpg"></body></html>'
            ).encode()
            return FetchedResource(url=url, data=html, content_type="text/html")
        if url == "https://brand-example.edu/images/applying-the-brand-900x600.jpg":
            return FetchedResource(url=url, data=thumbnail_bytes, content_type="image/jpeg")
        if url == "https://icon.edu/":
            html = (
                '<html><head><link rel="icon" title="Icon University logo" '
                'href="https://icon.edu/assets/icons/icon-university-app-icons-theme-white/192.png"></head></html>'
            ).encode()
            return FetchedResource(url=url, data=html, content_type="text/html")
        if url == "https://icon.edu/assets/icons/icon-university-app-icons-theme-white/192.png":
            return FetchedResource(url=url, data=png_bytes, content_type="image/png")
        if url == "https://evil.example/logo.png":
            return FetchedResource(url=url, data=png_bytes, content_type="image/png")
        raise AssertionError(f"unexpected fetch: {url}")

    identity_state = {
        "kind": "academic_identity_assets",
        "version": 1,
        "entities": [
            {"entity_name": "TestConf 2026", "role": "venue", "source": "manifest", "confidence": 0.82},
            {"entity_name": "Example University", "role": "institution", "source": "brief", "confidence": 0.72},
            {"entity_name": "Blocked University", "role": "institution", "source": "brief", "confidence": 0.72},
            {"entity_name": "Google Research", "role": "company", "source": "affiliation", "confidence": 0.84},
            {"entity_name": "Brand Example University", "role": "institution", "source": "brief", "confidence": 0.72},
            {"entity_name": "Icon University", "role": "institution", "source": "brief", "confidence": 0.72},
            {"entity_name": "Unknown College", "role": "institution", "source": "brief", "confidence": 0.72},
        ],
        "assets": [
            {
                "asset_id": "identity_badge_testconf",
                "entity_name": "TestConf 2026",
                "label": "TestConf 2026",
                "role": "venue",
                "asset_type": "text_badge",
                "safe_to_place": True,
            },
            {
                "asset_id": "identity_badge_example",
                "entity_name": "Example University",
                "label": "Example University",
                "role": "institution",
                "asset_type": "text_badge",
                "safe_to_place": True,
            },
            {
                "asset_id": "identity_badge_blocked",
                "entity_name": "Blocked University",
                "label": "Blocked University",
                "role": "institution",
                "asset_type": "text_badge",
                "safe_to_place": True,
            },
            {
                "asset_id": "identity_badge_brand_example",
                "entity_name": "Brand Example University",
                "label": "Brand Example University",
                "role": "institution",
                "asset_type": "text_badge",
                "safe_to_place": True,
            },
            {
                "asset_id": "identity_badge_icon_university",
                "entity_name": "Icon University",
                "label": "Icon University",
                "role": "institution",
                "asset_type": "text_badge",
                "safe_to_place": True,
            },
            {
                "asset_id": "identity_badge_unknown",
                "entity_name": "Unknown College",
                "label": "Unknown College",
                "role": "institution",
                "asset_type": "text_badge",
                "safe_to_place": True,
            },
            {
                "asset_id": "identity_badge_google",
                "entity_name": "Google Research",
                "label": "Google Research",
                "role": "company",
                "asset_type": "text_badge",
                "safe_to_place": True,
            },
        ],
    }
    rendered: dict[str, dict[str, Any]] = {}
    resolved = resolve_academic_identity_assets(
        identity_assets=identity_state,
        rendered_layers=rendered,
        run_dir=out_dir,
        layers_dir=layers_dir,
        allowlist_path=allowlist_path,
        fetcher=fake_fetch,
        enabled=True,
    )
    assets = resolved.get("assets") or []
    images = [asset for asset in assets if asset.get("asset_type") == "image"]
    if len(images) != 2:
        _fail(f"expected two resolved identity images, got {assets}")
    by_entity = {asset.get("entity_name"): asset for asset in images}
    testconf = by_entity.get("TestConf 2026")
    if not testconf or testconf.get("content_type") != "image/svg+xml":
        _fail(f"SVG preferred asset should resolve with SVG provenance: {testconf}")
    if not str(testconf.get("local_asset_path") or "").endswith(".png"):
        _fail(f"SVG asset should be rasterized to PNG for rendered_layers: {testconf}")
    if not Path(str(testconf.get("source_svg_path") or "")).exists():
        _fail(f"original SVG source should be retained beside raster output: {testconf}")
    example = by_entity.get("Example University")
    if not example or example.get("source_url") != "https://cdn.example.net/example-logo.png":
        _fail(f"official page CDN logo should resolve: {example}")
    if example.get("discovered_from_url") != "https://example.edu/brand":
        _fail(f"CDN logo should retain official discovered_from_url: {example}")
    for asset in images:
        layer_id = str(asset.get("rendered_layer_id") or "")
        rec = rendered.get(layer_id)
        if not rec or not rec.get("is_identity_asset"):
            _fail(f"resolved logo should register identity rendered_layer: {asset} / {rendered}")
        if not Path(str(asset.get("local_asset_path") or "")).exists():
            _fail(f"resolved logo local path missing: {asset}")

    result_by_entity = {
        item.get("entity_name"): item
        for item in ((resolved.get("search") or {}).get("results") or [])
        if isinstance(item, dict)
    }
    blocked = result_by_entity.get("Blocked University") or {}
    if blocked.get("status") != "not_found":
        _fail(f"blocked external asset should not resolve: {blocked}")
    blocked_reasons = {item.get("reason") for item in blocked.get("rejected") or []}
    if "asset_host_not_allowlisted" not in blocked_reasons:
        _fail(f"blocked external asset should record reject reason: {blocked}")
    if "https://evil.example/logo.png" in fetch_calls:
        _fail("disallowed direct external asset should be rejected before fetch")
    unknown = result_by_entity.get("Unknown College") or {}
    if unknown.get("status") != "no_allowlist_rule":
        _fail(f"unknown entities should fall back to text badge: {unknown}")
    google = result_by_entity.get("Google Research") or {}
    if google.get("status") != "not_found":
        _fail(f"Google Research thumbnail should be rejected, not resolved: {google}")
    google_reasons = {item.get("reason") for item in google.get("rejected") or []}
    if not ({"candidate_logo_hint_missing", "non_logo_official_page_media"} & google_reasons):
        _fail(f"Google Research video thumbnail should record non-logo rejection: {google}")
    brand_example = result_by_entity.get("Brand Example University") or {}
    if brand_example.get("status") != "not_found":
        _fail(f"official brand usage image should be rejected, not resolved: {brand_example}")
    brand_example_reasons = {item.get("reason") for item in brand_example.get("rejected") or []}
    if "non_logo_official_page_media" not in brand_example_reasons:
        _fail(f"official brand usage image should record non-logo rejection: {brand_example}")
    icon_university = result_by_entity.get("Icon University") or {}
    if icon_university.get("status") != "not_found":
        _fail(f"official page app icon should be rejected, not resolved: {icon_university}")
    icon_reasons = {item.get("reason") for item in icon_university.get("rejected") or []}
    if "candidate_icon_not_logo" not in icon_reasons and "asset_path_blocked" not in icon_reasons:
        _fail(f"official page app icon should record icon rejection: {icon_university}")
    if "https://icon.edu/assets/icons/icon-university-app-icons-theme-white/192.png" in fetch_calls:
        _fail("official page app icon should be rejected before fetch")
    remaining_badges = {
        asset.get("entity_name")
        for asset in assets
        if asset.get("asset_type") == "text_badge"
    }
    if remaining_badges != {
        "Blocked University",
        "Brand Example University",
        "Google Research",
        "Icon University",
        "Unknown College",
    }:
        _fail(f"resolved entities should drop redundant text badges: {remaining_badges}")
    metrics = resolved.get("metrics") or {}
    status_counts = metrics.get("identity_search_status_counts") or {}
    if (
        metrics.get("identity_search_resolved_count") != 2
        or metrics.get("image_asset_count") != 2
        or status_counts.get("resolved") != 2
        or status_counts.get("no_allowlist_rule") != 1
        or status_counts.get("not_found") != 4
    ):
        _fail(f"resolver metrics should count resolved logos: {metrics}")
    agent_logo_buf = BytesIO()
    Image.new("RGBA", (220, 88), (255, 255, 255, 0)).save(agent_logo_buf, format="PNG")
    agent_logo_bytes = agent_logo_buf.getvalue()

    def fake_agent_fetch(url: str, max_bytes: int) -> FetchedResource:
        if url == "https://example.edu/assets/example-university-logo.png":
            return FetchedResource(url=url, data=agent_logo_bytes, content_type="image/png")
        raise AssertionError(f"unexpected agent fetch: {url}")

    rendered_agent: dict[str, dict[str, Any]] = {}
    updated_agent, agent_resolution = resolve_designer_identity_logo_candidates(
        identity_assets={
            "kind": "academic_identity_assets",
            "version": 1,
            "entities": [{"entity_name": "Example University", "role": "institution"}],
            "assets": [],
        },
        rendered_layers=rendered_agent,
        run_dir=out_dir,
        layers_dir=layers_dir,
        candidates=[{
            "entity_name": "Example University",
            "role": "institution",
            "source_url": "https://example.edu/assets/example-university-logo.png",
            "discovered_from_url": "https://example.edu/brand",
            "confidence": 0.93,
            "required_to_place": True,
        }],
        allowlist_path=allowlist_path,
        fetcher=fake_agent_fetch,
        enabled=True,
        source="identity_logo_agent",
        resolver_name="identity_logo_agent",
        state_key="identity_logo_agent_resolution",
    )
    if agent_resolution.get("resolved_count") != 1:
        _fail(f"identity logo agent candidate should resolve: {agent_resolution}")
    agent_image = next(
        (asset for asset in (updated_agent.get("assets") or []) if asset.get("asset_type") == "image"),
        None,
    )
    if not agent_image or agent_image.get("source") != "identity_logo_agent":
        _fail(f"agent-resolved logo should preserve source: {updated_agent}")
    _ok("allowlist SVG, official-page CDN, rejected external, and badge fallback paths wired")


def check_identity_logo_agent_modes_no_api() -> None:
    print("[8c/53] identity logo agent modes (no API)")
    import shutil

    from .agents.identity_logo_agent import IdentityLogoAgent
    from .config import REPO_ROOT, Settings
    from .tools import ToolContext

    out_dir = REPO_ROOT / "out" / "smoke_identity_logo_agent"
    if out_dir.exists():
        shutil.rmtree(out_dir)
    layers_dir = out_dir / "layers"
    layers_dir.mkdir(parents=True, exist_ok=True)
    identity_state = {
        "kind": "academic_identity_assets",
        "version": 1,
        "entities": [{
            "entity_name": "Missing University",
            "role": "institution",
            "required_to_place": True,
            "placement_intent": "verified_affiliation",
        }],
        "assets": [],
    }

    auto_settings = Settings(
        anthropic_api_key="sk-stub", anthropic_base_url=None,
        gemini_api_key="stub", designer_model="stub", critic_model="stub",
        identity_logo_agent_mode="auto",
        identity_logo_agent_cmd="",
    )
    auto_ctx = ToolContext(settings=auto_settings, run_dir=out_dir, layers_dir=layers_dir,
                           run_id="smoke-identity-logo-auto")
    auto_state, auto_result = IdentityLogoAgent(auto_settings).run(
        ctx=auto_ctx,
        identity_assets=dict(identity_state),
    )
    if auto_result.get("status") != "skipped_no_command" or auto_result.get("required"):
        _fail(f"auto identity logo agent should fail open when command is missing: {auto_result}")
    if (auto_state.get("identity_logo_agent") or {}).get("status") != "skipped_no_command":
        _fail(f"auto skip should be recorded in identity state: {auto_state}")

    required_settings = Settings(
        anthropic_api_key="sk-stub", anthropic_base_url=None,
        gemini_api_key="stub", designer_model="stub", critic_model="stub",
        identity_logo_agent_mode="required",
        identity_logo_agent_cmd="",
    )
    required_ctx = ToolContext(settings=required_settings, run_dir=out_dir, layers_dir=layers_dir,
                               run_id="smoke-identity-logo-required")
    required_state, required_result = IdentityLogoAgent(required_settings).run(
        ctx=required_ctx,
        identity_assets=dict(identity_state),
    )
    if (
        required_result.get("status") != "error"
        or not required_result.get("required")
        or not required_result.get("blocking")
    ):
        _fail(f"required identity logo agent should record blocking error: {required_result}")
    if (required_state.get("identity_logo_agent") or {}).get("status") != "error":
        _fail(f"required error should be recorded in identity state: {required_state}")

    custom_allowlist = out_dir / "agent_allowlist.json"
    custom_allowlist.write_text(json.dumps({"version": 1, "rules": []}), encoding="utf-8")
    fake_cmd = out_dir / "fake_identity_logo_agent.py"
    fake_cmd.write_text(
        "import json\n"
        "from pathlib import Path\n"
        "Path('identity_logo_candidates.json').write_text(json.dumps({\n"
        "  'version': 1,\n"
        "  'candidates': [{\n"
        "    'entity_name': 'Missing University',\n"
        "    'role': 'institution',\n"
        "    'source_url': 'https://missing.example/logo.png',\n"
        "    'discovered_from_url': 'https://missing.example/brand',\n"
        "    'confidence': 0.91\n"
        "  }]\n"
        "}))\n",
        encoding="utf-8",
    )
    passthrough_settings = Settings(
        anthropic_api_key="sk-stub", anthropic_base_url=None,
        gemini_api_key="stub", designer_model="stub", critic_model="stub",
        identity_logo_agent_mode="auto",
        identity_logo_agent_cmd=f"{sys.executable} {fake_cmd}",
    )
    import autodesign.agents.identity_logo_agent as identity_logo_agent_module

    captured: dict[str, Any] = {}
    original_resolver = identity_logo_agent_module.resolve_designer_identity_logo_candidates

    def fake_resolver(**kwargs: Any) -> tuple[dict[str, Any], dict[str, Any]]:
        captured["allowlist_path"] = kwargs.get("allowlist_path")
        updated = dict(kwargs.get("identity_assets") or {})
        return updated, {"status": "ok", "resolved_count": 0}

    try:
        identity_logo_agent_module.resolve_designer_identity_logo_candidates = fake_resolver
        passthrough_ctx = ToolContext(
            settings=passthrough_settings,
            run_dir=out_dir,
            layers_dir=layers_dir,
            run_id="smoke-identity-logo-allowlist-path",
        )
        IdentityLogoAgent(passthrough_settings).run(
            ctx=passthrough_ctx,
            identity_assets=dict(identity_state),
            allowlist_path=custom_allowlist,
        )
    finally:
        identity_logo_agent_module.resolve_designer_identity_logo_candidates = original_resolver
    if captured.get("allowlist_path") != custom_allowlist:
        _fail(f"identity logo agent should pass custom allowlist path to materializer: {captured}")
    _ok("identity logo agent auto/required missing-command modes wired")


def check_academic_identity_curation_no_api() -> None:
    print("[8d/53] academic identity offline curation runner (no API)")
    import importlib.util
    import shutil

    from .config import REPO_ROOT
    from .util.academic_identity_search import FetchedResource

    script_path = REPO_ROOT / "scripts" / "curate_academic_identity_library.py"
    spec = importlib.util.spec_from_file_location("curate_academic_identity_library", script_path)
    if spec is None or spec.loader is None:
        _fail(f"failed to load curation script: {script_path}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)

    out_dir = REPO_ROOT / "out" / "smoke_identity_curation"
    if out_dir.exists():
        shutil.rmtree(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    source_allowlist_path = out_dir / "source_allowlist.json"
    original_allowlist = {
        "version": 1,
        "rules": [{
            "id": "institution-existing-university",
            "entity_name": "Existing University",
            "role": "institution",
            "aliases": ["Existing University"],
            "official_domains": ["existing.edu"],
            "preferred_asset_urls": ["https://existing.edu/logo.png"],
            "confidence": 0.82,
        }],
    }
    source_allowlist_path.write_text(json.dumps(original_allowlist, ensure_ascii=False, indent=2), encoding="utf-8")
    original_bytes = source_allowlist_path.read_bytes()

    png_buf = BytesIO()
    Image.new("RGBA", (180, 72), (18, 52, 86, 255)).save(png_buf, format="PNG")
    png_bytes = png_buf.getvalue()
    hero_buf = BytesIO()
    Image.new("RGB", (1600, 900), (220, 220, 220)).save(hero_buf, format="JPEG")
    hero_bytes = hero_buf.getvalue()

    def fake_fetch(url: str, max_bytes: int) -> FetchedResource:
        if url == "https://existing.edu/logo.png":
            return FetchedResource(url=url, data=png_bytes, content_type="image/png")
        if url == "https://curation.edu/brand":
            html_doc = (
                '<html><body><img alt="Curation University logo" '
                'src="https://curation.edu/assets/curation-logo.png"></body></html>'
            ).encode()
            return FetchedResource(url=url, data=html_doc, content_type="text/html")
        if url == "https://curation.edu/assets/curation-logo.png":
            return FetchedResource(url=url, data=png_bytes, content_type="image/png")
        if url == "https://hero.edu/brand":
            html_doc = (
                '<html><body><img alt="Hero University brand" '
                'src="https://hero.edu/images/hero-banner.jpg"></body></html>'
            ).encode()
            return FetchedResource(url=url, data=html_doc, content_type="text/html")
        if url == "https://hero.edu/images/hero-banner.jpg":
            return FetchedResource(url=url, data=hero_bytes, content_type="image/jpeg")
        raise AssertionError(f"unexpected curation fetch: {url}")

    target_rules = [
        module._rule(
            "institution-existing-university",
            "Existing University",
            "institution",
            ["Existing"],
            ["existing.edu"],
            homepages=["https://existing.edu/brand"],
        ),
        module._rule(
            "institution-curation-university",
            "Curation University",
            "institution",
            ["Curation U"],
            ["curation.edu"],
            homepages=["https://curation.edu/brand"],
        ),
        module._rule(
            "institution-hero-university",
            "Hero University",
            "institution",
            ["Hero U"],
            ["hero.edu"],
            homepages=["https://hero.edu/brand"],
        ),
    ]
    result = module.run_curation(
        out_dir=out_dir,
        target_rules=target_rules,
        identity_logo_agent="off",
        fetcher=fake_fetch,
        base_allowlist_path=source_allowlist_path,
    )
    if source_allowlist_path.read_bytes() != original_bytes:
        _fail("offline curation runner must not mutate source allowlist")
    for name in ("index.html", "accepted_candidates.json", "rejected_candidates.json", "proposed_allowlist.json", "allowlist.patch"):
        if not (out_dir / name).exists():
            _fail(f"curation runner should write {name}")
    accepted = json.loads((out_dir / "accepted_candidates.json").read_text(encoding="utf-8"))
    accepted_entities = {item.get("entity_name") for item in accepted.get("candidates") or []}
    if accepted_entities != {"Existing University", "Curation University"}:
        _fail(f"curation should accept only verified logo assets: {accepted}")
    rejected = json.loads((out_dir / "rejected_candidates.json").read_text(encoding="utf-8"))
    hero_rows = [item for item in rejected.get("candidates") or [] if item.get("entity_name") == "Hero University"]
    if not hero_rows or not any(
        item.get("reason") in {"non_logo_official_page_media", "candidate_logo_hint_missing"}
        for item in hero_rows
    ):
        _fail(f"curation should reject hero/banner media: {rejected}")
    proposed = json.loads((out_dir / "proposed_allowlist.json").read_text(encoding="utf-8"))
    existing_rule = next((rule for rule in proposed.get("rules") or [] if rule.get("id") == "institution-existing-university"), {})
    if "https://existing.edu/logo.png" not in (existing_rule.get("preferred_asset_urls") or []):
        _fail(f"curation should preserve existing preferred assets: {existing_rule}")
    curation_rule = next((rule for rule in proposed.get("rules") or [] if rule.get("id") == "institution-curation-university"), {})
    if "https://curation.edu/assets/curation-logo.png" not in (curation_rule.get("preferred_asset_urls") or []):
        _fail(f"curation should add accepted source URL to proposed allowlist: {curation_rule}")
    if not (out_dir / "allowlist.patch").read_text(encoding="utf-8").strip():
        _fail("curation should write a non-empty allowlist patch draft")
    if result.get("accepted_count") != 2:
        _fail(f"curation summary should report accepted candidates: {result}")

    import autodesign.agents.identity_logo_agent as identity_logo_agent_module

    agent_out_dir = REPO_ROOT / "out" / "smoke_identity_curation_agent_scope"
    if agent_out_dir.exists():
        shutil.rmtree(agent_out_dir)
    agent_out_dir.mkdir(parents=True, exist_ok=True)
    fake_agent_cmd = agent_out_dir / "fake_agent.py"
    fake_agent_cmd.write_text(
        "import json\n"
        "from pathlib import Path\n"
        "Path('identity_logo_candidates.json').write_text(json.dumps({\n"
        "  'version': 1,\n"
        "  'candidates': [\n"
        "    {'entity_name': 'Target Agent University', 'role': 'institution', 'source_url': 'https://target-agent.edu/logo.png'},\n"
        "    {'entity_name': 'Unrelated University', 'role': 'institution', 'source_url': 'https://unrelated.edu/logo.png'}\n"
        "  ]\n"
        "}))\n",
        encoding="utf-8",
    )
    original_agent_resolver = identity_logo_agent_module.resolve_designer_identity_logo_candidates

    def fake_agent_resolver(**kwargs: Any) -> tuple[dict[str, Any], dict[str, Any]]:
        updated = dict(kwargs.get("identity_assets") or {})
        assets = list(updated.get("assets") or [])
        for name in ("Target Agent University", "Unrelated University"):
            assets.append({
                "asset_id": f"identity_logo_{name.lower().replace(' ', '_')}",
                "entity_name": name,
                "role": "institution",
                "asset_type": "image",
                "safe_to_place": True,
                "source_url": f"https://{name.lower().replace(' ', '-')}.edu/logo.png",
                "discovery_method": "identity_logo_agent",
            })
        updated["assets"] = assets
        return updated, {"status": "ok", "resolved_count": 2}

    try:
        identity_logo_agent_module.resolve_designer_identity_logo_candidates = fake_agent_resolver
        agent_result = module.run_curation(
            out_dir=agent_out_dir,
            target_rules=[
                module._rule(
                    "institution-target-agent-university",
                    "Target Agent University",
                    "institution",
                    ["Target Agent"],
                    ["target-agent.edu"],
                ),
            ],
            identity_logo_agent="auto",
            identity_logo_agent_cmd=f"{sys.executable} {fake_agent_cmd}",
            fetcher=fake_fetch,
            base_allowlist_path=source_allowlist_path,
        )
    finally:
        identity_logo_agent_module.resolve_designer_identity_logo_candidates = original_agent_resolver
    agent_accepted = json.loads((agent_out_dir / "accepted_candidates.json").read_text(encoding="utf-8"))
    agent_accepted_entities = {item.get("entity_name") for item in agent_accepted.get("candidates") or []}
    if agent_accepted_entities != {"Target Agent University"} or agent_result.get("accepted_count") != 1:
        _fail(f"agent-assisted curation should ignore unrelated agent assets: {agent_accepted}")
    _ok("offline curation draft/report flow preserves source allowlist")


def check_academic_identity_library_no_api() -> None:
    print("[8e/53] academic identity curated library (no API)")
    from urllib.parse import urlparse

    from .config import REPO_ROOT
    from .util.academic_identity import build_academic_identity_assets
    from .util.academic_identity_search import (
        find_allowlist_rule,
        host_allowed_for_identity_url,
        load_academic_identity_allowlist,
    )

    allowlist_path = REPO_ROOT / "assets" / "academic_identity" / "allowlist.json"
    if not allowlist_path.exists():
        _fail(f"academic identity allowlist missing: {allowlist_path}")
    allowlist = load_academic_identity_allowlist(allowlist_path)
    rules = allowlist.get("rules") or []
    if len(rules) < 35:
        _fail(f"curated allowlist should cover common entities; got {len(rules)} rules")

    ids: set[str] = set()
    for rule in rules:
        rule_id = str(rule.get("id") or "")
        if not rule_id or rule_id in ids:
            _fail(f"allowlist rule ids must be unique and non-empty: {rule}")
        ids.add(rule_id)
        domains = [str(item).lower().strip(".") for item in (rule.get("official_domains") or [])]
        if not domains:
            _fail(f"allowlist rule missing official_domains: {rule}")
        for field in ("homepages", "preferred_page_urls", "preferred_asset_urls"):
            for url in rule.get(field) or []:
                parsed = urlparse(str(url))
                if parsed.scheme != "https" or not parsed.hostname:
                    _fail(f"{rule_id}.{field} must be https URL: {url}")
                allowed_domains = domains
                if field == "preferred_asset_urls":
                    allowed_domains = domains + [
                        str(item).lower().strip(".")
                        for item in (rule.get("allowed_asset_domains") or [])
                    ]
                host = parsed.hostname.lower()
                if not any(host == domain or host.endswith("." + domain) for domain in allowed_domains):
                    _fail(f"{rule_id}.{field} host outside official domains: {url}")

    expected_matches = {
        "NeurIPS 2026": "venue-neurips",
        "MIT CSAIL": "lab-mit-csail",
        "Stanford University": "institution-stanford",
        "OpenAI": "company-openai",
        "CVPR": "venue-cvpr",
    }
    for label, expected_id in expected_matches.items():
        rule = find_allowlist_rule(label, allowlist=allowlist)
        if not rule or rule.get("id") != expected_id:
            _fail(f"allowlist failed to match {label!r}: {rule}")
    if not host_allowed_for_identity_url("openai.com", entity_name="OpenAI", allowlist=allowlist):
        _fail("OpenAI official host should be allowlisted for OpenAI")
    if host_allowed_for_identity_url("wikimedia.org", entity_name="OpenAI", allowlist=allowlist):
        _fail("Wikimedia should not be allowlisted as an OpenAI identity source")
    identity_payload = build_academic_identity_assets(
        summaries=[
            {
                "manifest": {
                    "title": "Logo Smoke",
                    "authors": ["A. Author"],
                    "venue": "ICLR 2026",
                    "affiliations": ["MIT", "Harvard University"],
                },
                "raw_text": (
                    "Logo Smoke\nA. Author\nMIT Laboratory for Computational Physiology\n"
                    "Beth Israel Deaconess Medical Center\nAbstract\n"
                    "Related work mentions NeurIPS and CVPR but they are not this paper's venue."
                ),
            },
            {
                "manifest": {
                    "title": "Second Paper",
                    "authors": ["B. Author"],
                    "venue": None,
                    "affiliations": ["Microsoft Research", "Alpha University", "Beta Lab"],
                },
                "raw_text": "Second Paper\nB. Author\nMicrosoft Research\nAbstract\nA method paper.",
            },
        ],
        rendered_layers={},
        brief="",
    )
    entities = identity_payload.get("entities") or []
    entity_names = {item.get("entity_name") for item in entities}
    expected_entity_names = {
        "ICLR 2026",
        "MIT",
        "Harvard University",
        "Microsoft Research",
        "Alpha University",
        "Beta Lab",
    }
    if not expected_entity_names.issubset(entity_names):
        _fail(f"identity extraction should include venue plus manifest/front-matter affiliations: {entities}")
    if "NeurIPS" in entity_names or "CVPR" in entity_names:
        _fail(f"related-work venue mentions should not become heading identity assets: {entities}")
    assets = identity_payload.get("assets") or []
    affiliation_badges = {
        asset.get("entity_name")
        for asset in assets
        if asset.get("entity_name") in expected_entity_names - {"ICLR 2026"}
        and asset.get("asset_type") == "text_badge"
    }
    if not (expected_entity_names - {"ICLR 2026"}).issubset(affiliation_badges):
        _fail(f"unresolved affiliations should expose editable text badges: {assets}")
    required_affiliations = {
        item.get("entity_name")
        for item in entities
        if item.get("source") == "affiliation" and item.get("required_to_place")
    }
    if not (expected_entity_names - {"ICLR 2026"}).issubset(required_affiliations):
        _fail(f"verified affiliations should be required-to-place resolver targets: {entities}")
    _ok(f"{len(rules)} curated rules validate and common aliases resolve")


def check_conference_poster_defaults_no_api() -> None:
    print("[4b/53] canvas planning defaults (no API)")
    from .config import REPO_ROOT, Settings, resolve_template
    from .runner import _apply_template_prologue, _select_effective_template
    from .tools import ToolContext
    from .tools.propose_paper_poster_html import _canvas_for_html_first, _join_css
    from .tools.propose_design_spec import propose_design_spec
    from .util.canvas_planner import (
        plan_canvas,
        refine_canvas_plan_from_ingest,
    )
    from .util.deck_planner import (
        plan_deck,
        validate_deck_plan_report,
    )

    canvas = resolve_template("conference_poster_portrait")
    if not canvas:
        _fail("conference-poster-portrait template not registered")
    if (canvas.get("w_px"), canvas.get("h_px")) != (2172, 3072):
        _fail(f"conference-poster-portrait dims wrong: {canvas}")
    if canvas.get("aspect_ratio") != "1:1.414":
        _fail(f"conference-poster-portrait aspect wrong: {canvas}")
    wide_canvas = resolve_template("academic-wide-2x1")
    if not wide_canvas:
        _fail("academic-wide-2x1 template not registered")
    if (wide_canvas.get("w_px"), wide_canvas.get("h_px"), wide_canvas.get("dpi")) != (3072, 1536, 150):
        _fail(f"academic-wide-2x1 dims wrong: {wide_canvas}")
    wide_balanced_canvas = resolve_template("academic-wide-3280x1860")
    if not wide_balanced_canvas:
        _fail("academic-wide-3280x1860 template not registered")
    if (
        wide_balanced_canvas.get("w_px"),
        wide_balanced_canvas.get("h_px"),
        wide_balanced_canvas.get("dpi"),
        wide_balanced_canvas.get("aspect_ratio"),
    ) != (3072, 1536, 150, "2:1"):
        _fail(f"academic-wide-3280x1860 legacy alias dims wrong: {wide_balanced_canvas}")
    landscape_canvas = resolve_template("academic-landscape-1.414")
    if not landscape_canvas:
        _fail("academic-landscape-1.414 template not registered")
    if (
        landscape_canvas.get("w_px"),
        landscape_canvas.get("h_px"),
        landscape_canvas.get("aspect_ratio"),
    ) != (3072, 1536, "2:1"):
        _fail(f"academic-landscape-1.414 legacy alias dims wrong: {landscape_canvas}")
    cvpr_canvas = resolve_template("cvpr-landscape")
    if not cvpr_canvas:
        _fail("cvpr-landscape template not registered")
    if (
        cvpr_canvas.get("w_px"),
        cvpr_canvas.get("h_px"),
        cvpr_canvas.get("dpi"),
        cvpr_canvas.get("aspect_ratio"),
    ) != (3072, 1536, 150, "2:1"):
        _fail(f"cvpr-landscape dims wrong: {cvpr_canvas}")

    pdfs = [Path("paper.pdf")]
    selected = _select_effective_template(
        "给我生成这个 paper 的学术海报",
        pdfs,
        None,
    )
    if selected is not None:
        _fail(f"adaptive canvas planning should replace implicit template; got {selected!r}")
    selected = _select_effective_template("make slides from this paper", pdfs, None)
    if selected is not None:
        _fail(f"deck intent should not receive poster default: {selected!r}")
    selected = _select_effective_template("make a landing page", pdfs, None)
    if selected is not None:
        _fail(f"landing intent should not receive poster default: {selected!r}")
    selected = _select_effective_template("横版学术海报", pdfs, None)
    if selected is not None:
        _fail(f"landscape intent should not receive portrait default: {selected!r}")
    selected = _select_effective_template("poster", pdfs, "a0-landscape")
    if selected != "a0-landscape":
        _fail(f"explicit template should win; got {selected!r}")
    hard_plan = plan_canvas("poster", pdfs, requested_template=selected)
    if hard_plan.get("preset_id") != "a0-landscape" or hard_plan.get("lock_level") != "hard":
        _fail(f"explicit template should produce hard a0-landscape plan: {hard_plan}")
    balanced_wide_plan = plan_canvas("poster", pdfs, requested_template="academic-wide-3280x1860")
    if (
        balanced_wide_plan.get("preset_id") != "cvpr-landscape"
        or balanced_wide_plan.get("lock_level") != "hard"
        or balanced_wide_plan.get("poster_subtype") != "academic_paper_cvpr_landscape"
        or (balanced_wide_plan.get("body_grid") or {}).get("family") != "editorial_3col"
    ):
        _fail(f"legacy academic wide template should canonicalize to hard editorial CVPR plan: {balanced_wide_plan}")
    balanced_budget = balanced_wide_plan.get("density_budget") or {}
    if balanced_budget.get("target_visuals_min") != 6 or balanced_budget.get("visual_area_min") != 0.42:
        _fail(f"legacy wide template should use CVPR academic budget: {balanced_wide_plan}")

    user_hard_plan = plan_canvas("make this as an A0 landscape poster", [])
    if user_hard_plan.get("preset_id") != "a0-landscape" or user_hard_plan.get("lock_level") != "hard":
        _fail(f"explicit user A0 landscape wording should hard-lock: {user_hard_plan}")

    demo_plan = plan_canvas(
        "Generate a poster for the DEMO text-to-video motion paper with qualitative frame comparisons.",
        pdfs,
    )
    if demo_plan.get("artifact_type") != "poster":
        _fail(f"text-to-video paper poster should remain poster, got {demo_plan}")
    if (
        demo_plan.get("preset_id") != "cvpr-landscape"
        or demo_plan.get("lock_level") != "soft"
        or (demo_plan.get("body_grid") or {}).get("family") != "editorial_3col"
    ):
        _fail(f"DEMO motion paper poster should use the editorial three-column grid: {demo_plan}")

    event_plan = plan_canvas("movie poster for a jazz festival", [])
    if event_plan.get("preset_id") != "event-2x3":
        _fail(f"generic event/movie poster should choose event-2x3: {event_plan}")
    event_canvas = event_plan.get("canvas") or {}
    if not (event_canvas.get("h_px", 0) > event_canvas.get("w_px", 0)):
        _fail(f"event-2x3 should be portrait-oriented: {event_canvas}")

    ambiguous_plan = plan_canvas("poster", [])
    if ambiguous_plan.get("lock_level") != "advisory":
        _fail(f"ambiguous poster should be advisory: {ambiguous_plan}")

    base_plan = plan_canvas("academic paper poster", pdfs)
    if base_plan.get("preset_id") != "cvpr-landscape":
        _fail(f"academic paper poster should default to CVPR landscape: {base_plan}")
    if (base_plan.get("body_grid") or {}).get("family") != "editorial_3col":
        _fail(f"academic paper poster should default to the editorial three-column grid: {base_plan}")
    explicit_landscape = plan_canvas("横版学术海报", pdfs)
    if explicit_landscape.get("preset_id") != "cvpr-landscape":
        _fail(f"explicit landscape paper poster should use cvpr-landscape: {explicit_landscape}")
    rendered = {
        f"ingest_fig_{i:02d}": {
            "image_size": "1600x700",
            "caption": "qualitative video frame comparison motion grid",
        }
        for i in range(1, 7)
    }
    refined = refine_canvas_plan_from_ingest(
        base_plan,
        [{"type": "pdf", "registered_figure_ids": list(rendered)}],
        rendered,
    )
    if (
        not refined
        or refined.get("preset_id") != "cvpr-landscape"
        or (refined.get("body_grid") or {}).get("family") != "editorial_3col"
    ):
        _fail(f"wide/video ingest signals should keep editorial three-column grid: {refined}")
    budget = refined.get("density_budget") or {}
    if budget.get("max_visuals") != 10 or budget.get("target_visuals_min") != 6:
        _fail(f"CVPR academic density budget should target dense three-column posters: {refined}")
    table_pressure_layers = {
        f"ingest_table_{i:02d}": {
            "kind": "table",
            "caption": "benchmark result table with ablation rows",
            "image_size": "1000x700",
        }
        for i in range(1, 3)
    }
    table_pressure = refine_canvas_plan_from_ingest(
        base_plan,
        [{"type": "pdf", "registered_table_ids": list(table_pressure_layers)}],
        table_pressure_layers,
    )
    if (
        not table_pressure
        or table_pressure.get("preset_id") != "cvpr-landscape"
        or (table_pressure.get("body_grid") or {}).get("family") != "editorial_3col"
    ):
        _fail(f"table/text pressure should keep editorial three-column grid: {table_pressure}")

    prologue = _apply_template_prologue("brief", "conference-poster-portrait")
    if "Template: conference-poster-portrait" not in prologue or "w_px=2172" not in prologue:
        _fail("conference-poster-portrait prologue missing expected canvas")

    out_dir = REPO_ROOT / "out" / "smoke_canvas_plan"
    settings = Settings(
        anthropic_api_key="sk-stub",
        anthropic_base_url=None,
        gemini_api_key="stub",
        designer_model="claude-opus-4-7",
        critic_model="claude-opus-4-7",
    )

    def _canvas_context(run_id: str) -> ToolContext:
        run_dir = out_dir / run_id
        layers_dir = run_dir / "layers"
        layers_dir.mkdir(parents=True, exist_ok=True)
        return ToolContext(
            settings=settings,
            run_dir=run_dir,
            layers_dir=layers_dir,
            run_id=run_id,
        )

    soft_ctx = _canvas_context("smoke-canvas-plan-soft")
    soft_ctx.state["canvas_plan"] = demo_plan
    planner_stale_canvas = {"w_px": 3072, "h_px": 2172, "dpi": 150, "aspect_ratio": "1.414:1", "color_mode": "RGB"}
    plan_canvas_record = demo_plan.get("canvas") or {}
    html_first_canvas = _canvas_for_html_first({"canvas": planner_stale_canvas}, soft_ctx)
    if (
        html_first_canvas.get("w_px"),
        html_first_canvas.get("h_px"),
        html_first_canvas.get("aspect_ratio"),
    ) != (
        plan_canvas_record.get("w_px"),
        plan_canvas_record.get("h_px"),
        plan_canvas_record.get("aspect_ratio"),
    ):
        _fail(f"HTML-first poster canvas should prefer active canvas_plan over stale args canvas: {html_first_canvas}")
    override_canvas = _canvas_for_html_first(
        {"canvas": {**planner_stale_canvas, "canvas_plan_override_reason": "smoke explicit override"}},
        soft_ctx,
    )
    if (
        override_canvas.get("w_px"),
        override_canvas.get("h_px"),
        override_canvas.get("aspect_ratio"),
    ) != (
        plan_canvas_record.get("w_px"),
        plan_canvas_record.get("h_px"),
        plan_canvas_record.get("aspect_ratio"),
    ):
        _fail(f"HTML-first poster canvas should ignore planner-stale override when canvas_plan is active: {override_canvas}")
    no_plan_ctx = _canvas_context("smoke-canvas-no-plan")
    no_plan_override_canvas = _canvas_for_html_first(
        {"canvas": {**planner_stale_canvas, "canvas_plan_override_reason": "smoke explicit override"}},
        no_plan_ctx,
    )
    if (no_plan_override_canvas.get("w_px"), no_plan_override_canvas.get("h_px")) != (3072, 2172):
        _fail(f"HTML-first poster canvas should preserve explicit override only without active canvas_plan: {no_plan_override_canvas}")
    joined_css = _join_css(
        ".paper-poster{width:3072px;height:2172px}",
        "",
        canvas=html_first_canvas,
    )
    if (
        f"width:{plan_canvas_record.get('w_px')}px!important" not in joined_css
        or f"height:{plan_canvas_record.get('h_px')}px!important" not in joined_css
    ):
        _fail(f"HTML-first poster CSS should lock root canvas to active plan: {joined_css}")
    soft_spec = {
        "brief": "soft canvas mismatch smoke",
        "artifact_type": "poster",
        "canvas": {"w_px": 2048, "h_px": 1536, "dpi": 300, "aspect_ratio": "4:3", "color_mode": "RGB"},
        "palette": ["#111111", "#ffffff"],
        "typography": {"title_font": "NotoSansSC-Bold"},
        "mood": ["test"],
        "composition_notes": "smoke",
        "layer_graph": [],
    }
    obs = propose_design_spec({"design_spec": soft_spec}, ctx=soft_ctx)
    if obs.status != "error" or obs.error_category != "validation":
        _fail(f"soft 2:1 plan should reject incompatible 4:3 without override: {obs}")

    override_spec = json.loads(json.dumps(soft_spec))
    override_spec["canvas"]["canvas_plan_override_reason"] = (
        "Client requested a compact gallery board for this smoke."
    )
    obs = propose_design_spec({"design_spec": override_spec}, ctx=soft_ctx)
    if obs.status != "error" or obs.error_category != "validation":
        _fail(f"fixed CVPR canvas should reject canvas_plan_override_reason mismatches: {obs}")

    auto_expand_ctx = _canvas_context("smoke-canvas-plan-auto-expand")
    auto_expand_ctx.state["canvas_plan"] = demo_plan
    auto_expand_spec = json.loads(json.dumps(soft_spec))
    auto_expand_spec["canvas"]["canvas_auto_expand_reason"] = "measured_blocks_exceeded_soft_canvas"
    obs = propose_design_spec({"design_spec": auto_expand_spec}, ctx=auto_expand_ctx)
    if obs.status != "error" or obs.error_category != "validation":
        _fail(f"fixed CVPR canvas should reject HTML auto-expanded canvas mismatches: {obs}")

    advisory_ctx = _canvas_context("smoke-canvas-plan-advisory")
    advisory_ctx.state["canvas_plan"] = ambiguous_plan
    advisory_spec = json.loads(json.dumps(soft_spec))
    advisory_spec["canvas"] = {
        "w_px": 1080,
        "h_px": 1920,
        "dpi": 300,
        "aspect_ratio": "9:16",
        "color_mode": "RGB",
    }
    obs = propose_design_spec({"design_spec": advisory_spec}, ctx=advisory_ctx)
    if obs.status != "ok":
        _fail(f"advisory plan should not block mismatched canvas: {obs}")

    alias_ctx = _canvas_context("smoke-propose-schema-alias")
    alias_spec = json.loads(json.dumps(soft_spec))
    alias_spec["canvas"] = {
        "w_px": 1200,
        "h_px": 800,
        "dpi": 150,
        "aspect_ratio": "3:2",
        "color_mode": "RGB",
    }
    alias_spec["layer_graph"] = [{
        "layer_id": "decor_shape",
        "name": "Decor Shape",
        "kind": "shape",
        "z_index": "1",
        "bbox": {"x": "20px", "y": "30px", "w": "200px", "h": "80px"},
        "letter_spacing": "-0.02em",
    }]
    alias_spec["html_artifact"] = {
        "target": "poster",
        "frames": [{
            "frame_id": "poster_canvas",
            "kind": "canvas",
            "layout_plan": {
                "archetype": "schema_repair_smoke",
                "slots": [{"slot_id": "hero", "role": "visual"}],
            },
            "blocks": [
                {
                    "block_id": "hero",
                    "kind": "background",
                    "bbox": {"x": "40px", "y": "60px", "w": "320px", "h": "180px"},
                },
                {
                    "block_id": "copy",
                    "kind": "text",
                    "text": "Schema alias repair",
                    "bbox": {"x": 420, "y": 80, "w": 420, "h": 90},
                },
            ],
        }],
    }
    obs = propose_design_spec({"designSpec": alias_spec}, ctx=alias_ctx)
    if obs.status != "ok":
        _fail(f"propose_design_spec should accept common schema aliases/coercions: {obs}")
    repaired_spec = alias_ctx.state.get("design_spec")
    repaired_dump = repaired_spec.model_dump(mode="json")
    slot_bbox = repaired_dump["html_artifact"]["frames"][0]["layout_plan"]["slots"][0].get("bbox")
    if not slot_bbox or repaired_dump["html_artifact"]["frames"][0]["blocks"][0]["kind"] != "shape":
        _fail("propose_design_spec did not repair missing slot bbox/background block kind")
    bad_spec = json.loads(json.dumps(alias_spec))
    bad_spec["layer_graph"] = [{
        "name": "Missing id",
        "kind": "text",
        "z_index": 1,
        "bbox": {"x": 1, "y": 1, "w": 10, "h": 10},
        "text": "X" * 2000,
    }]
    bad_spec.pop("html_artifact", None)
    obs = propose_design_spec({"design_spec": bad_spec}, ctx=alias_ctx)
    if obs.status != "error" or "X" * 80 in (obs.error_message or ""):
        _fail("propose_design_spec validation error should omit huge input payloads")

    hard_deck = plan_deck("Create 8 slides from this paper", pdfs, canvas_plan={"artifact_type": "deck"})
    if hard_deck.get("slide_count") != 8 or hard_deck.get("lock_level") != "hard":
        _fail(f"explicit slide count should hard-lock deck_plan: {hard_deck}")
    exact_hyphen_deck = plan_deck("Create a 12-page deck from this paper", pdfs, canvas_plan={"artifact_type": "deck"})
    if exact_hyphen_deck.get("slide_count") != 12 or exact_hyphen_deck.get("lock_level") != "hard":
        _fail(f"explicit 12-page wording should hard-lock deck_plan: {exact_hyphen_deck}")
    range_deck = plan_deck("Create 8-10 slides from this paper", pdfs, canvas_plan={"artifact_type": "deck"})
    if range_deck.get("slide_count") is not None or range_deck.get("lock_level") == "hard" or range_deck.get("count_range") != [8, 10]:
        _fail(f"slide count ranges should not become hard exact locks: {range_deck}")
    negated_count_deck = plan_deck(
        "Create a deck from this paper; do not default to a fixed 18-slide outline.",
        pdfs,
        canvas_plan={"artifact_type": "deck"},
    )
    if negated_count_deck.get("slide_count") is not None or negated_count_deck.get("lock_level") == "hard":
        _fail(f"negated 18-slide wording should not hard-lock deck_plan: {negated_count_deck}")
    pending_deck = plan_deck("Create an academic slide deck from this paper", pdfs, canvas_plan={"artifact_type": "deck"})
    if pending_deck.get("slide_count") != 18 or pending_deck.get("lock_level") != "soft":
        _fail(f"academic source deck without explicit count should use the soft 18-slide default: {pending_deck}")

    def deck_spec(n: int, *, override: str | None = None) -> dict[str, Any]:
        spec = {
            "brief": f"{n} slide deck smoke",
            "artifact_type": "deck",
            "canvas": {"w_px": 1920, "h_px": 1080, "dpi": 96, "aspect_ratio": "16:9", "color_mode": "RGB"},
            "palette": ["#111111", "#ffffff"],
            "typography": {"display": "NotoSerifSC-Bold", "body": "NotoSansSC-Bold"},
            "mood": ["test"],
            "composition_notes": "deck_plan smoke",
            "html_artifact": {
                "target": "deck",
                "frames": [
                    {"frame_id": f"slide_{i:02d}", "kind": "slide", "blocks": []}
                    for i in range(1, n + 1)
                ],
            },
        }
        if override:
            spec["deck_plan_override_reason"] = override
        return spec

    pending_ctx = _canvas_context("smoke-deck-plan-pending")
    pending_ctx.state["deck_plan"] = negated_count_deck
    obs = propose_design_spec({"design_spec": deck_spec(1)}, ctx=pending_ctx)
    if obs.status != "ok":
        _fail(f"pending deck_plan should not block validation before refinement: {obs}")

    soft_deck_plan = dict(pending_deck)
    soft_deck_plan.update({
        "slide_count": 14,
        "count_range": [14, 14],
        "status": "refined",
        "source": "smoke",
        "lock_level": "soft",
        "outline": [
            {"slide_index": i, "title": f"Slide {i}", "role": "content", "content": "x", "visual_refs": []}
            for i in range(1, 15)
        ],
    })
    deck_ctx = _canvas_context("smoke-deck-plan-soft")
    deck_ctx.state["deck_plan"] = soft_deck_plan
    obs = propose_design_spec({"design_spec": deck_spec(12)}, ctx=deck_ctx)
    if obs.status != "error" or obs.error_category != "validation":
        _fail(f"soft deck_plan should reject 12 slides when 14 planned: {obs}")
    obs = propose_design_spec({"design_spec": deck_spec(12, override="Short seminar format requested.")}, ctx=deck_ctx)
    if obs.status != "ok":
        _fail(f"soft deck_plan mismatch should pass with override reason: {obs}")
    advisory_deck_ctx = _canvas_context("smoke-deck-plan-advisory")
    advisory_plan = dict(soft_deck_plan)
    advisory_plan["lock_level"] = "advisory"
    advisory_deck_ctx.state["deck_plan"] = advisory_plan
    obs = propose_design_spec({"design_spec": deck_spec(12)}, ctx=advisory_deck_ctx)
    if obs.status != "ok":
        _fail(f"advisory deck_plan mismatch should not block: {obs}")

    valid_plan = dict(soft_deck_plan)
    model, errors = validate_deck_plan_report(valid_plan, known_visual_refs=set())
    if errors or model is None:
        _fail(f"valid deck_plan report should pass validation: {errors}")
    invalid_plan = dict(valid_plan)
    invalid_plan["outline"] = invalid_plan["outline"][:-1]
    _model, errors = validate_deck_plan_report(invalid_plan, known_visual_refs=set())
    if not errors:
        _fail("deck_plan report with outline length mismatch should fail")

    _ok("adaptive canvas planner and deck planner select, refine, and validate plans")


def check_web_artifact_type_inference_no_api() -> None:
    print("[4c/53] web artifact type inference (no API)")
    from scripts.web_server import _coerce_artifact_type

    cases = [
        (None, "再给这个paper生成一个page", "landing"),
        (None, "build a project page for this paper", "landing"),
        (None, "make slides from this paper", "deck"),
        (None, "给我生成一个学术海报", "poster"),
        ("poster", "make a landing page", "poster"),
    ]
    for raw, brief, expected in cases:
        got = _coerce_artifact_type(raw, brief=brief)
        if got != expected:
            _fail(f"artifact inference wrong for {brief!r}: {got!r} != {expected!r}")
    _ok("brief-only page/slides/poster intents infer expected artifact types")


def check_composite_no_api() -> None:
    """Build a fake background + 2 real text layers, run composite end-to-end.

    Also exercises switch_artifact_type → propose_design_spec plumbing
    (artifact_type fallback from ctx.state when spec omits it).
    """
    print("[5/53] composite (no API)")
    from .config import REPO_ROOT, Settings
    from .tools import ToolContext
    from .tools.composite import composite
    from .tools.generate_background import generate_background
    from .tools.propose_design_spec import propose_design_spec
    from .tools.render_text_layer import render_text_layer
    from .tools.switch_artifact_type import switch_artifact_type

    out_dir = REPO_ROOT / "out" / "smoke"
    layers_dir = out_dir / "layers"
    layers_dir.mkdir(parents=True, exist_ok=True)

    settings = Settings(
        anthropic_api_key="sk-stub",
        anthropic_base_url=None,
        gemini_api_key="stub",
        designer_model="claude-opus-4-7",
        critic_model="claude-opus-4-7",
        poster_preview_max_edge=512,
    )
    ctx = ToolContext(settings=settings, run_dir=out_dir,
                      layers_dir=layers_dir, run_id="smoke")

    # First: switch_artifact_type — verifies ctx.state update + valid type
    obs = switch_artifact_type({"type": "poster"}, ctx=ctx)
    if obs.status != "ok":
        _fail(f"switch_artifact_type: {(obs.error_message or str(obs.payload))}")
    if ctx.state.get("artifact_type") != "poster":
        _fail(f"ctx.state.artifact_type not set; got {ctx.state.get('artifact_type')}")

    # Reject invalid type (paranoia — catches the enum drift)
    bad = switch_artifact_type({"type": "billboard"}, ctx=ctx)
    if bad.status != "error":
        _fail(f"switch_artifact_type should reject 'billboard'; got status={bad.status}")

    # Spec omits artifact_type on purpose — should fall back to ctx.state value
    spec_args = {"design_spec": {
        "brief": "smoke test poster",
        "canvas": {"w_px": 768, "h_px": 1024, "dpi": 150,
                   "aspect_ratio": "3:4", "color_mode": "RGB"},
        "palette": ["#1a1a1a", "#ffffff", "#a02018"],
        "typography": {"title_font": "NotoSerifSC",
                       "subtitle_font": "NotoSansSC"},
        "mood": ["test"],
        "composition_notes": "smoke",
        "layer_graph": [],
    }}
    obs = propose_design_spec(spec_args, ctx=ctx)
    if obs.status != "ok":
        _fail(f"propose_design_spec: {(obs.error_message or str(obs.payload))}")

    # Fallback check: spec omitted artifact_type → should inherit ctx.state value
    stored_spec = ctx.state["design_spec"]
    if stored_spec.artifact_type.value != "poster":
        _fail(f"artifact_type fallback failed; got {stored_spec.artifact_type.value!r}")

    style_out_dir = REPO_ROOT / "out" / "smoke_typography_fallback"
    style_layers_dir = style_out_dir / "layers"
    style_layers_dir.mkdir(parents=True, exist_ok=True)
    style_ctx = ToolContext(settings=settings, run_dir=style_out_dir,
                            layers_dir=style_layers_dir, run_id="smoke-typography-fallback")
    switch_artifact_type({"type": "poster"}, ctx=style_ctx)
    obs = propose_design_spec({"design_spec": {
        "brief": "smoke typography fallback",
        "artifact_type": "poster",
        "canvas": {"w_px": 768, "h_px": 1024, "dpi": 150,
                   "aspect_ratio": "3:4", "color_mode": "RGB"},
        "palette": ["#f7f2e8", "#1c1917"],
        "typography": {"display": "NotoSerifSC", "body": "NotoSansSC"},
        "mood": ["test"],
        "composition_notes": "smoke typography fallback",
        "layer_graph": [{
            "layer_id": "L_style_from_spec", "name": "style_from_spec",
            "kind": "text", "z_index": 1,
            "bbox": {"x": 40, "y": 40, "w": 688, "h": 160},
            "text": "Hierarchy", "font_family": "NotoSerifSC",
            "font_size_px": 72, "font_weight": 710,
            "font_style": "italic", "line_height": 0.98,
            "letter_spacing": 1.25, "text_transform": "uppercase",
            "align": "left",
        }],
    }}, ctx=style_ctx)
    if obs.status != "ok":
        _fail(f"typography fallback spec: {(obs.error_message or str(obs.payload))}")
    obs = render_text_layer({
        "layer_id": "L_style_from_spec", "name": "style_from_spec",
        "text": "Hierarchy", "font_family": "NotoSerifSC",
        "font_size_px": 72, "fill": "#1c1917",
        "bbox": {"x": 40, "y": 40, "w": 688, "h": 160},
        "align": "left", "z_index": 1,
    }, ctx=style_ctx)
    if obs.status != "ok":
        _fail(f"typography fallback render: {(obs.error_message or str(obs.payload))}")
    fallback_layer = style_ctx.state["rendered_layers"]["L_style_from_spec"]
    if (
        fallback_layer.get("font_weight") != 710
        or fallback_layer.get("font_style") != "italic"
        or fallback_layer.get("line_height") != 0.98
        or fallback_layer.get("letter_spacing") != 1.25
        or fallback_layer.get("text_transform") != "uppercase"
    ):
        _fail(f"render_text_layer did not inherit typography from spec: {fallback_layer}")

    paper_out_dir = out_dir / "smoke-paper-bg"
    paper_layers_dir = paper_out_dir / "layers"
    paper_layers_dir.mkdir(parents=True, exist_ok=True)
    paper_ctx = ToolContext(settings=settings, run_dir=paper_out_dir,
                            layers_dir=paper_layers_dir, run_id="smoke-paper-bg")
    switch_artifact_type({"type": "poster"}, ctx=paper_ctx)
    obs = propose_design_spec(spec_args, ctx=paper_ctx)
    if obs.status != "ok":
        _fail(f"paper poster guard spec setup failed: {obs.error_message}")
    paper_ctx.state["ingested"] = [{"type": "pdf", "registered_layer_ids": ["ingest_fig_01"]}]
    obs = generate_background({
        "layer_id": "L0_bg",
        "prompt": "calm cream academic texture. No text, no characters, no lettering, no symbols, no logos, no watermarks.",
        "aspect_ratio": "3:4",
        "image_size": "1K",
    }, ctx=paper_ctx)
    if obs.status != "error" or obs.error_category != "validation":
        _fail("paper poster should reject default generated background before API call")

    bg_path = layers_dir / "bg_smoke.png"
    Image.new("RGB", (768, 1024), (28, 14, 10)).save(bg_path)
    ctx.state["rendered_layers"]["L0_bg"] = {
        "layer_id": "L0_bg", "name": "background", "kind": "background", "z_index": 0,
        "bbox": {"x": 0, "y": 0, "w": 768, "h": 1024},
        "src_path": str(bg_path), "prompt": "(stub)",
        "aspect_ratio": "3:4", "image_size": "1K",
        "safe_zones": [], "sha256": "stub",
    }

    obs = render_text_layer({
        "layer_id": "L1_title", "name": "title", "text": "国宝回家",
        "font_family": "NotoSerifSC", "font_size_px": 110, "font_weight": 720,
        "line_height": 1.04, "letter_spacing": 2, "text_transform": "none",
        "fill": "#fafafa",
        "bbox": {"x": 48, "y": 80, "w": 672, "h": 180}, "align": "center",
        "z_index": 1,
        "effects": {"shadow": {"color": "#00000080", "dx": 0, "dy": 4, "blur": 12}},
    }, ctx=ctx)
    if obs.status != "ok":
        _fail(f"render_text_layer title: {(obs.error_message or str(obs.payload))}")

    obs = render_text_layer({
        "layer_id": "L2_subtitle", "name": "subtitle",
        "text": "National Treasures Return Home",
        "font_family": "NotoSansSC", "font_size_px": 36, "font_weight": 460,
        "line_height": 1.22, "fill": "#c9a45a",
        # Intentionally too high: composite should repair the overlap with
        # the title before writing PSD/SVG/HTML/preview.
        "bbox": {"x": 64, "y": 210, "w": 640, "h": 60}, "align": "center",
        "z_index": 2,
    }, ctx=ctx)
    if obs.status != "ok":
        _fail(f"render_text_layer subtitle: {(obs.error_message or str(obs.payload))}")

    obs = composite({}, ctx=ctx)
    if obs.status != "ok":
        _fail(f"composite: {(obs.error_message or str(obs.payload))}")
    if not obs.payload.get("poster_layout_repairs"):
        _fail("poster layout repair should have moved the overlapping subtitle")
    if obs.payload.get("text_overlap_warnings"):
        _fail(f"poster text overlaps remained after repair: {obs.payload['text_overlap_warnings']}")
    if "layout_grounding_warnings" not in obs.payload:
        _fail("poster composite payload missing layout_grounding_warnings")
    if "quality_lint_findings" not in obs.payload:
        _fail("poster composite payload missing quality_lint_findings")
    if obs.payload.get("quality_lint_p0_count") != 0:
        _fail(f"poster smoke should have no P0 quality lint findings: {obs.payload.get('quality_lint_findings')}")
    if "paper_density_findings" not in obs.payload:
        _fail("poster composite payload missing paper_density_findings")
    if obs.payload.get("paper_density_p0_count") != 0:
        _fail(f"non-paper poster smoke should have no density P0 findings: {obs.payload.get('paper_density_findings')}")
    if "poster_preview_fallback_used" not in obs.payload:
        _fail("poster composite payload missing poster_preview_fallback_used")
    if "preview_scale" not in obs.payload:
        _fail("poster composite payload missing preview_scale")
    preview_path = Path(obs.payload["preview_relative_path"])
    preview_path = out_dir / preview_path
    with Image.open(preview_path) as preview_img:
        if max(preview_img.size) > 512:
            _fail(f"poster preview long edge should be <=512; got {preview_img.size}")
        if obs.payload.get("preview_canvas_w_px") != preview_img.size[0]:
            _fail("poster preview_canvas_w_px should match preview.png width")
        if obs.payload.get("preview_canvas_h_px") != preview_img.size[1]:
            _fail("poster preview_canvas_h_px should match preview.png height")
    if obs.payload.get("layout_grounding_backend") == "playwright":
        bad = [
            issue for issue in obs.payload.get("layout_grounding_issues", [])
            if issue.get("severity") == "high" and issue.get("type") == "text_text_overlap"
        ]
        if bad:
            _fail(f"browser grounding text overlap remained: {bad}")
        if not obs.payload.get("layout_grounding_relative_path"):
            _fail("poster composite missing layout_grounding_relative_path")
    elif not obs.payload.get("layout_grounding_warnings"):
        _fail("non-playwright grounding must return an explicit warning")

    comp = ctx.state["composition"]
    for label, p in [("PSD", comp.psd_path), ("SVG", comp.svg_path),
                     ("HTML", comp.html_path), ("preview", comp.preview_path)]:
        if p is None:
            _fail(f"{label} path missing on CompositionArtifacts")
        path = Path(p)
        if not path.exists() or path.stat().st_size == 0:
            _fail(f"{label} not written: {p}")
        _ok(f"{label} {path.name} ({path.stat().st_size // 1024} KB)")


