def check_poster_typesetting_patch_no_api() -> None:
    print("[5b/53] poster final typesetting rhythm patch (no API)")
    import shutil

    from .agents.external_designer_author import _typesetting_fit_regressed
    from .util.poster_typesetting import apply_poster_typesetting_patch, revert_poster_typesetting_patch

    out_dir = Path("out/smoke_poster_typesetting")
    if out_dir.exists():
        shutil.rmtree(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    html_path = out_dir / "poster.html"
    html_path.write_text(
        """<!doctype html><html><head><style>.paper-poster p{line-height:1}</style></head><body>
<main class="paper-poster editorial-poster">
  <section class="poster-section" data-block-id="section_1">
    <h2 data-block-id="heading_1">Motivation</h2>
    <p data-block-id="body_1">Dominant sequence models couple computation through recurrence and limit parallelism.</p>
    <ul data-block-id="list_1">
      <li data-block-id="li_1">Self-attention connects all positions through one native operation.</li>
      <li data-block-id="li_2">Parallel training becomes practical while preserving long-range access.</li>
    </ul>
  </section>
</main></body></html>""",
        encoding="utf-8",
    )
    record = apply_poster_typesetting_patch(
        html_path,
        record_path=out_dir / "typesetting.json",
        backup_path=out_dir / "poster.before.html",
        phase="smoke",
    )
    patched = html_path.read_text(encoding="utf-8")
    if not record.get("applied"):
        _fail(f"poster typesetting patch did not apply: {record}")
    if patched.count('data-od-auto-repair="typesetting-rhythm-v1"') != 1:
        _fail("poster typesetting patch should inject exactly one marker style")
    if (
        "list-style-position:outside!important" not in patched
        or ".paper-poster ul>li::marker" not in patched
        or ".source-flow-unit,.figure-flow-unit" not in patched
        or "--od-source-flow-bullet-indent:1.25em" not in patched
        or "padding-inline-start:var(--od-source-flow-bullet-indent)!important" not in patched
        or ".paper-poster ul>li::before" in patched
    ):
        _fail("poster typesetting patch should use native markers with source-flow list gutter CSS")
    second = apply_poster_typesetting_patch(html_path, record_path=out_dir / "typesetting_second.json", phase="smoke")
    if second.get("reason") != "already_current":
        _fail(f"poster typesetting patch should be idempotent: {second}")
    if not revert_poster_typesetting_patch(record):
        _fail("poster typesetting patch did not revert from backup")
    reverted = html_path.read_text(encoding="utf-8")
    if "typesetting-rhythm-v1" in reverted:
        _fail("poster typesetting revert left marker CSS behind")
    if not _typesetting_fit_regressed(
        {"available": True, "missingRoot": False, "scrollWidth": 3072, "scrollHeight": 1536},
        {"available": True, "missingRoot": False, "scrollWidth": 3072, "scrollHeight": 1538},
        {"w_px": 3072, "h_px": 1536},
    ):
        _fail("poster typesetting guard should reject newly introduced root overflow")
    if _typesetting_fit_regressed(
        {"available": True, "missingRoot": False, "scrollWidth": 3072, "scrollHeight": 1953},
        {"available": True, "missingRoot": False, "scrollWidth": 3072, "scrollHeight": 1891},
        {"w_px": 3072, "h_px": 1536},
    ):
        _fail("poster typesetting guard should allow root overflow improvement")
    _ok("poster typesetting patch is idempotent and reversible")


def check_identity_header_purity_regression_no_api() -> None:
    print("[3c3/53] identity-header purity regression (no API)")
    from bs4 import BeautifulSoup

    from .config import Settings
    from .tools import ToolContext
    from .tools.propose_paper_poster_html import _identity_header_only_error

    ctx = ToolContext(
        settings=Settings(
            anthropic_api_key="sk-stub",
            anthropic_base_url=None,
            gemini_api_key="stub",
            designer_model="stub",
            critic_model="stub",
        ),
        run_dir=Path("/tmp/autodesign-identity-header-smoke"),
        layers_dir=Path("/tmp/autodesign-identity-header-smoke/layers"),
        run_id="smoke-identity-header-purity",
    )

    cases = (
        ("paper-institution", "Southern University of Science and Technology", None),
        ("paper-institutions", "Southern University of Science and Technology", None),
        ("paper-affiliation", "Southern University of Science and Technology", None),
        ("paper-affiliations", "Southern University of Science and Technology", None),
        ("institutions", "CVPR 2026", "identity_header_nonidentity_allowed_role_text"),
        ("institutions", "Project Aurora", "identity_header_nonidentity_allowed_role_text"),
        (
            "institutions",
            "Unified multimodal research framework",
            "identity_header_nonidentity_allowed_role_text",
        ),
    )
    for class_name, row_text, expected_issue_id in cases:
        soup = BeautifulSoup(
            "<main><header class='poster-header' data-panel-role='identity_header'>"
            "<h1>Paper Title</h1><p class='authors'>Ada Author, Ben Author</p>"
            f"<p class='{class_name}'>{row_text}</p>"
            "</header></main>",
            "html.parser",
        )
        error = _identity_header_only_error(soup, ctx)
        issue_ids = {
            str(issue.get("id") or "")
            for issue in ((error.payload or {}).get("issues") if error else [])
            if isinstance(issue, dict)
        }
        if expected_issue_id is None:
            if error:
                _fail(
                    f"identity header should allow {class_name} row {row_text!r}: {error}"
                )
        elif expected_issue_id not in issue_ids:
            _fail(
                f"identity header should reject {class_name} row {row_text!r} "
                f"with {expected_issue_id}: {error}"
            )
    _ok("identity-header institution rows allow university names and reject non-identity text")


