        def _all_text_lanes_on_expected_side() -> bool:
            if not text_lanes:
                return False
            def same_source_column_below(bbox: dict[str, Any]) -> bool:
                x = int(bbox.get("x") or 0)
                y = int(bbox.get("y") or 0)
                w = int(bbox.get("w") or 0)
                return (
                    abs(x - source_left) <= 2
                    and abs(w - int(source_lane.get("w") or 0)) <= 2
                    and y >= source_bottom
                )
