def _assert_office_visual_ineligible(
    payload: Any,
    *,
    figure_id: str,
    fixture_label: str,
) -> None:
    if not isinstance(payload, dict):
        _fail(f"{fixture_label} payload should be a mapping: {payload}")
    recommended = payload.get("recommended_figures")
    if not isinstance(recommended, dict):
        _fail(f"{fixture_label} recommended_figures should be a mapping: {recommended}")
    malformed_buckets = {
        bucket: ids for bucket, ids in recommended.items() if not isinstance(ids, list)
    }
    if malformed_buckets:
        _fail(f"{fixture_label} recommendation buckets should be lists: {malformed_buckets}")
    if any(figure_id in ids for ids in recommended.values()):
        _fail(f"{fixture_label} should not be recommended: {recommended}")

    poster_brief = payload.get("poster_content_brief")
    if not isinstance(poster_brief, dict):
        _fail(f"{fixture_label} poster_content_brief should be a mapping: {poster_brief}")
    visual_selection = poster_brief.get("visual_selection")
    if not isinstance(visual_selection, dict):
        _fail(f"{fixture_label} visual_selection should be a mapping: {visual_selection}")
    primary_visual_ids = visual_selection.get("primary_visual_ids")
    if not isinstance(primary_visual_ids, list):
        _fail(f"{fixture_label} primary_visual_ids should be a list: {primary_visual_ids}")
    forbidden_visual_ids = visual_selection.get("forbidden_visual_ids")
    if not isinstance(forbidden_visual_ids, list):
        _fail(f"{fixture_label} forbidden_visual_ids should be a list: {forbidden_visual_ids}")
    if figure_id in primary_visual_ids:
        _fail(f"{fixture_label} should not be a primary visual: {poster_brief}")
    if figure_id not in forbidden_visual_ids:
        _fail(f"{fixture_label} should be forbidden for poster selection: {poster_brief}")


def check_ingest_document_docx() -> None:
    """Docx ingestion (v1.2.5): build a minimal Word doc with headings +
    an inline image, verify ingest_document extracts sections + figures
    without any VLM call."""
