    with fitz.open(taxonomy_pdf) as probe_doc:
        clean_flags = pdf_table_crop_quality_flags(probe_doc[0], clean_table)
        if "table_without_structure" in clean_flags or "table_fragment_crop" in clean_flags:
            _fail(f"clean non-numeric taxonomy table should remain usable: {clean_flags}")
        fragment_flags = pdf_table_crop_quality_flags(probe_doc[0], fragment)
