    out_root = REPO_ROOT / "out" / "smoke_external_designer_author"
    if out_root.exists():
        shutil.rmtree(out_root)
    out_root.mkdir(parents=True, exist_ok=True)

    def make_author_ctx(
        run_id: str,
        command: str,
        *,
        max_attempts: int = 1,
        timeout_s: int = 10,
        poster_stable_s: float = 0.5,
        poster_harness_mode: str | None = None,
        reference_profile: str | None = None,
        max_critique_iters: int = 0,
    ) -> ToolContext:
        run_dir = out_root / "runs" / run_id
        layers_dir = run_dir / "layers"
        layers_dir.mkdir(parents=True, exist_ok=True)
        settings_kwargs = {
            "designer_author_mode": "external",
            "designer_author_cmd": command,
            "designer_author_model": "smoke-model",
            "designer_author_timeout_s": timeout_s,
            "designer_author_max_attempts": max_attempts,
            "designer_author_poster_stable_s": poster_stable_s,
            "max_critique_iters": max_critique_iters,
        }
        if poster_harness_mode is not None:
            settings_kwargs["poster_harness_mode"] = poster_harness_mode
        settings = replace(_make_smoke_settings(out_root), **settings_kwargs)
        poster_plan_contract = {"selected_visuals": [], "required_sections": []}
        if reference_profile:
            poster_plan_contract["reference_profile"] = reference_profile
        color_system = select_academic_color_system(raw_brief="vision image multimodal poster")
        ctx = ToolContext(
            settings=settings,
            run_dir=run_dir,
            layers_dir=layers_dir,
            run_id=run_id,
        )
        ctx.state.update({
            "raw_user_brief": "Generate a poster for my paper",
            "run_brief": "Generate a poster for my paper",
            "attachments": [],
            "canvas_plan": {
                "w_px": 3072,
                "h_px": 1536,
                "preset_id": "cvpr-landscape",
                "canvas": {"w_px": 3072, "h_px": 1536},
            },
            "poster_content_brief": {
                "title": "Smoke Paper",
                "authors": ["OpenAI Research Team"],
                "affiliations": ["OpenAI"],
                "sections": [],
                "background_contract": {"allowed_fill": ["#FFFFFF"], "logo_policy": "fetch public logos"},
                "color_system": color_system,
                "recommended_color_system": color_system,
                "institution_color_signals": {
                    "organizations": ["OpenAI"],
                    "signal_strength": "strong",
                    "source": "paper_identity",
                    "selection_guidance": "Use institution/company/school names only as soft color associations.",
                },
            },
            "poster_plan_contract": poster_plan_contract,
            "paper_visual_provenance": {"assets": []},
            "paper_visual_storyboard": {"selected_assets": []},
            "paper_memory": {"chunks": []},
        })
        ctx.state["poster_plan_contract"]["color_system"] = color_system
        ctx.state["poster_plan_contract"]["background_policy"] = {"allowed_fill": ["#FFFFFF"], "logo_policy": "fetch public logos"}
        atomic_write_json(run_dir / "poster_content_brief.json", ctx.state["poster_content_brief"])
        atomic_write_json(run_dir / "poster_plan_contract.json", ctx.state["poster_plan_contract"])
        atomic_write_json(run_dir / "paper_visual_provenance.json", ctx.state["paper_visual_provenance"])
        atomic_write_json(run_dir / "paper_visual_storyboard.json", ctx.state["paper_visual_storyboard"])
        atomic_write_json(run_dir / "paper_memory.json", ctx.state["paper_memory"])
        atomic_write_json(run_dir / "canvas_plan.json", ctx.state["canvas_plan"])
        return ctx

