        build_panel_polish_context,
        compare_panel_scope,
        panel_polish_acceptance,
        panel_text_only_structure_report,
        parse_panel_visual_judge,
        parse_panel_visual_triage,
        select_panel_polish_targets,
        source_visual_lock_report,
